    ('Россия', 'Москва'),
    ('Россия', 'Владивосток'),
    ('Россия', 'Екатеринбург'),
    ('Россия', 'Казань'),
    ('Франция', 'Париж'),
    ('Франция', 'Версаль'),
    ('Италия', 'Рим'),
    ('Италия', 'Пиза'),
    ('Италия', 'Венеция'),
    ('Италия', 'Флоренция'),
    ('Испания', 'Барселона'),
    ('Испания', 'Севилья'),
    ('Испания', 'Мадрид'),
    ('США', 'Нью-Йорк'),
    ('США', 'Сан-Франциско'),
    ('США', 'Вашингтон'),
    ('Великобритания', 'Лондон'),
    ('Греция', 'Афины'),
    ('Австралия', 'Сидней'),
    ('Австрия', 'Вена'),
    ('Бразилия', 'Рио-де-Жанейро'),
    ('Германия', 'Берлин'),
    ('Египет', 'Гиза'),
    ('Индия', 'Агра'),
    ('Китай', 'Хуайжоу'),
    ('Китай', 'Пекин'),
    ('Мексика', 'Сан-Хуан-Теотиуакан'),
    ('Нидерланды', 'Амстердам'),
