ON CONFLICT (country_id, name) DO NOTHING;

INSERT INTO attractions
 (name, description, history, latitude, longitude, category_id, city_id)
SELECT v.name, v.description, v.history, v.latitude, v.longitude, cat.category_id, ci.city_id
FROM (VALUES
    ('Петергоф', 'Дворцово-парковый ансамбль на южном берегу Финского залива, известный фонтанами.', 'Создание резиденции Петра I началось в начале XVIII века. Большой дворец и система фонтанов стали центральными элементами ансамбля.', 59.884400::numeric, 29.908700::numeric, 'Дворцово-парковые ансамбли', 'Россия', 'Петергоф'),
    ('Эрмитаж', 'Один из крупнейших художественных и культурно-исторических музеев мира.', 'Музей ведёт историю с коллекции Екатерины II, начатой в 1764 году. Главный музейный комплекс расположен в зданиях Зимнего дворца и Малого, Старого и Нового Эрмитажа.', 59.939832::numeric, 30.314560::numeric, 'Музеи', 'Россия', 'Санкт-Петербург'),
    ('Собор Василия Блаженного', 'Православный храм на Красной площади, известный разноцветными куполами.', 'Построен в 1555–1561 годах по распоряжению Ивана IV в память о взятии Казани.', 55.752525::numeric, 37.623088::numeric, 'Религиозные сооружения', 'Россия', 'Москва'),
    ('Московский Кремль', 'Исторический архитектурный комплекс и действующая резиденция Президента России.', 'Крепость на Боровицком холме известна с XII века. Современный ансамбль стен и башен в основном сформировался в XV–XVII веках.', 55.752023::numeric, 37.617499::numeric, 'Исторические места', 'Россия', 'Москва'),
    ('Красная площадь', 'Главная площадь Москвы, расположенная у восточной стены Московского Кремля.', 'Сложилась как центральная торговая и общественная площадь города в конце XV века. Здесь находятся собор Василия Блаженного, Исторический музей и мавзолей.', 55.753930::numeric, 37.620795::numeric, 'Исторические места', 'Россия', 'Москва'),
    ('Лувр', 'Национальный музей Франции с обширной коллекцией произведений искусства.', 'Здание начиналось как крепость в конце XII века, позднее стало королевской резиденцией. Музей открылся для публики в 1793 году.', 48.860611::numeric, 2.337644::numeric, 'Музеи', 'Франция', 'Париж'),
    ('Эйфелева башня', 'Металлическая башня на Марсовом поле и один из самых узнаваемых символов Парижа.', 'Построена для Всемирной выставки 1889 года по проекту инженерной команды Гюстава Эйфеля.', 48.858370::numeric, 2.294481::numeric, 'Архитектура', 'Франция', 'Париж'),
    ('Колизей', 'Античный амфитеатр в центре Рима и один из крупнейших памятников Древнего Рима.', 'Строительство началось при императоре Веспасиане около 70 года н. э. и завершилось при Тите в 80 году.', 41.890210::numeric, 12.492231::numeric, 'Исторические места', 'Италия', 'Рим'),
    ('Саграда Фамилия', 'Католическая базилика, созданная по проекту Антонио Гауди.', 'Строительство началось в 1882 году. Гауди посвятил проекту значительную часть жизни; работы продолжаются и в XXI веке.', 41.403629::numeric, 2.174356::numeric, 'Религиозные сооружения', 'Испания', 'Барселона'),
    ('Статуя Свободы', 'Монумент на острове Свободы в Нью-Йоркской гавани.', 'Подарок Франции Соединённым Штатам, торжественно открытый в 1886 году. Статуя стала символом свободы и иммиграции.', 40.689249::numeric, -74.044500::numeric, 'Памятники', 'США', 'Нью-Йорк'),
    ('Биг-Бен', 'Обиходное название Большого колокола в часовой башне Вестминстерского дворца.', 'Часовая башня была завершена в середине XIX века. После реконструкции 2012–2017 годов получила официальное название Elizabeth Tower.', 51.500729::numeric, -0.124625::numeric, 'Архитектура', 'Великобритания', 'Лондон'),
    ('Афинский Акрополь', 'Древняя укреплённая возвышенность с выдающимися памятниками античной архитектуры.', 'Основные сооружения классического ансамбля, включая Парфенон, были построены в V веке до н. э. при Перикле.', 37.971532::numeric, 23.725749::numeric, 'Исторические места', 'Греция', 'Афины'),
    ('Золотой мост', 'Вантовый мост через бухту Золотой Рог во Владивостоке.', 'Мост открыли в 2012 году к саммиту АТЭС; он стал одной из узнаваемых частей городского пейзажа.', 43.111500::numeric, 131.898000::numeric, 'Архитектура', 'Россия', 'Владивосток'),
    ('Храм-на-Крови', 'Православный храм в Екатеринбурге, построенный на месте дома Ипатьева.', 'Храмовый комплекс был возведён в начале XXI века и освящён в 2003 году.', 56.842600::numeric, 60.609000::numeric, 'Религиозные сооружения', 'Россия', 'Екатеринбург'),
    ('Казанский кремль', 'Историческая крепость и архитектурный комплекс в центре Казани.', 'Кремль складывался на протяжении многих веков; его нынешний ансамбль включает памятники разных эпох.', 55.798500::numeric, 49.105400::numeric, 'Исторические места', 'Россия', 'Казань'),
    ('Кул-Шариф', 'Мечеть на территории Казанского кремля, один из символов Казани.', 'Современная мечеть открылась в 2005 году; её название напоминает о защитнике Казани Кул-Шарифе.', 55.798100::numeric, 49.105700::numeric, 'Религиозные сооружения', 'Россия', 'Казань'),
    ('Версальский дворец', 'Дворцово-парковый ансамбль к юго-западу от Парижа.', 'Дворец стал главной резиденцией французских королей при Людовике XIV в XVII веке.', 48.804900::numeric, 2.120400::numeric, 'Дворцово-парковые ансамбли', 'Франция', 'Версаль'),
    ('Триумфальная арка', 'Монумент на площади Шарля де Голля в Париже.', 'Арку начали строить по распоряжению Наполеона в 1806 году; строительство завершилось в 1836 году.', 48.873800::numeric, 2.295000::numeric, 'Памятники', 'Франция', 'Париж'),
    ('Нотр-Дам де Пари', 'Средневековый собор на острове Сите в центре Парижа.', 'Строительство готического собора началось в XII веке и продолжалось несколько столетий.', 48.853000::numeric, 2.349900::numeric, 'Религиозные сооружения', 'Франция', 'Париж'),
    ('Пизанская башня', 'Наклонная колокольня соборного комплекса на площади Чудес в Пизе.', 'Строительство башни началось в XII веке; наклон стал заметен ещё во время её возведения.', 43.723000::numeric, 10.396600::numeric, 'Архитектура', 'Италия', 'Пиза'),
    ('Собор Святого Марка', 'Собор на площади Сан-Марко в Венеции, известный мозаиками и византийским обликом.', 'Нынешний собор формировался с XI века и связан с историей Венецианской республики.', 45.434100::numeric, 12.339700::numeric, 'Религиозные сооружения', 'Италия', 'Венеция'),
    ('Собор Санта-Мария-дель-Фьоре', 'Кафедральный собор Флоренции с большим куполом Филиппо Брунеллески.', 'Строительство началось в 1296 году; купол был возведён в XV веке.', 43.773100::numeric, 11.256000::numeric, 'Религиозные сооружения', 'Италия', 'Флоренция'),
    ('Королевский Алькасар Севильи', 'Действующий королевский дворец и исторический комплекс в Севилье.', 'Дворец строился и перестраивался в разные эпохи; в его архитектуре сочетаются разные традиции.', 37.383100::numeric, -5.990300::numeric, 'Дворцово-парковые ансамбли', 'Испания', 'Севилья'),
    ('Музей Прадо', 'Национальный художественный музей Испании в Мадриде.', 'Музей открылся для публики в 1819 году и хранит коллекции испанского и европейского искусства.', 40.413800::numeric, -3.692100::numeric, 'Музеи', 'Испания', 'Мадрид'),
    ('Мост Золотые Ворота', 'Подвесной мост через пролив Золотые Ворота в Сан-Франциско.', 'Мост открылся в 1937 году и стал одним из символов города.', 37.819900::numeric, -122.478300::numeric, 'Архитектура', 'США', 'Сан-Франциско'),
    ('Мемориал Линкольна', 'Мемориал в честь президента Авраама Линкольна в Вашингтоне.', 'Здание мемориала было открыто в 1922 году.', 38.889300::numeric, -77.050200::numeric, 'Памятники', 'США', 'Вашингтон'),
    ('Британский музей', 'Музей истории и культуры народов мира в Лондоне.', 'Британский музей открылся для публики в 1759 году.', 51.519400::numeric, -0.127000::numeric, 'Музеи', 'Великобритания', 'Лондон'),
    ('Тауэрский мост', 'Разводной мост через Темзу рядом с Лондонским Тауэром.', 'Мост был открыт в 1894 году и стал важной частью инфраструктуры Лондона.', 51.505500::numeric, -0.075400::numeric, 'Архитектура', 'Великобритания', 'Лондон'),
    ('Сиднейский оперный театр', 'Оперный театр и концертный комплекс на берегу гавани Сиднея.', 'Здание, спроектированное Йорном Утзоном, открылось в 1973 году.', -33.856800::numeric, 151.215300::numeric, 'Архитектура', 'Австралия', 'Сидней'),
    ('Дворец Шёнбрунн', 'Дворцово-парковый комплекс в Вене.', 'Шёнбрунн был летней резиденцией Габсбургов; его ансамбль сформировался в XVII–XVIII веках.', 48.184500::numeric, 16.312200::numeric, 'Дворцово-парковые ансамбли', 'Австрия', 'Вена'),
    ('Статуя Христа-Искупителя', 'Монумент на вершине горы Корковаду с видом на Рио-де-Жанейро.', 'Статуя была открыта в 1931 году и стала одним из символов города.', -22.951900::numeric, -43.210500::numeric, 'Памятники', 'Бразилия', 'Рио-де-Жанейро'),
    ('Музейный остров', 'Комплекс музеев на острове реки Шпрее в центре Берлина.', 'Музеи комплекса создавались в XIX и XX веках; ансамбль включён в список Всемирного наследия ЮНЕСКО.', 52.516900::numeric, 13.401000::numeric, 'Музеи', 'Германия', 'Берлин'),
    ('Бранденбургские ворота', 'Монументальные городские ворота в центре Берлина.', 'Ворота были построены в конце XVIII века и стали одним из символов Берлина.', 52.516300::numeric, 13.377700::numeric, 'Исторические места', 'Германия', 'Берлин'),
    ('Пирамиды Гизы', 'Комплекс древнеегипетских пирамид на плато Гиза.', 'Крупнейшая пирамида комплекса была построена для фараона Хуфу в XXVI веке до н. э.', 29.979200::numeric, 31.134200::numeric, 'Археологические памятники', 'Египет', 'Гиза'),
    ('Тадж-Махал', 'Мавзолей из белого мрамора в городе Агра.', 'Комплекс был построен в XVII веке по приказу падишаха Шах-Джахана.', 27.175100::numeric, 78.042100::numeric, 'Исторические места', 'Индия', 'Агра'),
    ('Великая Китайская стена (Мутяньюй)', 'Участок Великой Китайской стены в районе Мутяньюй к северу от Пекина.', 'Участок Мутяньюй был построен и укреплён в период династии Мин.', 40.431900::numeric, 116.570400::numeric, 'Исторические места', 'Китай', 'Хуайжоу'),
    ('Запретный город', 'Дворцовый комплекс в центре Пекина, известный также как Гугун.', 'Комплекс служил резиденцией китайских императоров династий Мин и Цин; строительство началось в начале XV века.', 39.916300::numeric, 116.397200::numeric, 'Исторические места', 'Китай', 'Пекин'),
    ('Теотиуакан', 'Археологический комплекс с пирамидами Солнца и Луны.', 'Город возник задолго до ацтеков и был одним из крупнейших центров Мезоамерики.', 19.692500::numeric, -98.843800::numeric, 'Археологические памятники', 'Мексика', 'Сан-Хуан-Теотиуакан'),
    ('Рейксмюсеум', 'Национальный музей Нидерландов в Амстердаме.', 'Музей открылся в XIX веке; его коллекция посвящена искусству и истории Нидерландов.', 52.360000::numeric, 4.885200::numeric, 'Музеи', 'Нидерланды', 'Амстердам'),
    ('Голубая мечеть', 'Мечеть Султанахмет в историческом центре Стамбула.', 'Мечеть была построена в начале XVII века по распоряжению султана Ахмеда I.', 41.005400::numeric, 28.976800::numeric, 'Религиозные сооружения', 'Турция', 'Стамбул'),
    ('Собор Святой Софии', 'Исторический памятник архитектуры в Стамбуле.', 'Здание было построено как собор в VI веке, позднее использовалось как мечеть и музей; сейчас вновь действует как мечеть.', 41.008600::numeric, 28.980200::numeric, 'Религиозные сооружения', 'Турция', 'Стамбул'),
    ('Карлов мост', 'Средневековый каменный мост через Влтаву в Праге.', 'Строительство моста началось в XIV веке при короле Карле IV.', 50.086500::numeric, 14.411400::numeric, 'Архитектура', 'Чехия', 'Прага'),
    ('Кинкаку-дзи', 'Золотой павильон буддийского храмового комплекса в Киото.', 'Павильон был построен в XIV веке как загородная резиденция и позднее стал храмом.', 35.039400::numeric, 135.729200::numeric, 'Религиозные сооружения', 'Япония', 'Киото'),
    ('Токийская башня', 'Телевизионная и смотровая башня в Токио.', 'Башня открылась в 1958 году и была создана как телекоммуникационное сооружение.', 35.658600::numeric, 139.745400::numeric, 'Архитектура', 'Япония', 'Токио')
) AS v(name, description, history, latitude, longitude, category_name, country_name, city_name)
JOIN categories cat ON cat.name = v.category_name
JOIN countries co ON co.name = v.country_name
JOIN cities ci ON ci.country_id = co.country_id AND ci.name = v.city_name
WHERE NOT EXISTS (
    SELECT 1 FROM attractions a
    WHERE a.name = v.name AND a.city_id = ci.city_id
);


-- Первая проверенная партия каталога: 10 государств, ранее без достопримечательностей.
-- Координаты взяты из географических данных UNESCO World Heritage Centre.
-- Повторный запуск не создаёт дубликаты городов и достопримечательностей.
INSERT INTO cities (country_id, name)
SELECT co.country_id, v.city_name
FROM (VALUES
    ('Канада', 'Квебек'),
    ('Марокко', 'Айт-Бен-Хадду'),
    ('Норвегия', 'Берген'),
    ('Польша', 'Краков'),
    ('Португалия', 'Лиссабон'),
    ('Иордания', 'Вади-Муса'),
    ('Индонезия', 'Боробудур'),
    ('Кения', 'Момбаса'),
    ('Таиланд', 'Аюттхая'),
    ('Республика Корея', 'Сеул')
) AS v(country_name, city_name)
JOIN countries co ON co.name = v.country_name
ON CONFLICT (country_id, name) DO NOTHING;

INSERT INTO attractions
 (name, description, history, latitude, longitude, category_id, city_id)
SELECT v.name, v.description, v.history, v.latitude, v.longitude, cat.category_id, ci.city_id
FROM (VALUES
    ('Исторический район Старого Квебека',
     'Исторический городской ансамбль с крепостными стенами, бастионами, воротами и кварталами Верхнего и Нижнего города.',
     'Квебек основан Самюэлем де Шампленом в начале XVII века. Город был столицей Новой Франции, а после 1760 года — британской колонии. Сохранившиеся укрепления делают его одним из наиболее целостных примеров укреплённого колониального города Северной Америки.',
     46.809444::numeric, -71.210556::numeric, 'Исторические места', 'Канада', 'Квебек'),
    ('Ксар Айт-Бен-Хадду',
     'Укреплённое поселение на южных склонах Высокого Атласа, состоящее из глинобитных домов, башен и общественных сооружений внутри оборонительных стен.',
     'Ксар расположен на историческом торговом пути между древним Суданом и Марракешем. Сохранившиеся постройки демонстрируют традиционные техники земляного строительства юга Марокко; старейшие сооружения комплекса относятся не ранее чем к XVII веку.',
     31.047220::numeric, -7.128890::numeric, 'Архитектура', 'Марокко', 'Айт-Бен-Хадду'),
    ('Брюгген',
     'Историческая деревянная набережная Бергена с рядами узких зданий, обращённых фасадами к гавани.',
     'Брюгген связан с торговой деятельностью Ганзейского союза. В 1350 году в Бергене было создано ганзейское торговое представительство. После многочисленных пожаров квартал восстанавливали с сохранением средневековой планировки и традиционных деревянных конструкций.',
     60.397494::numeric, 5.324228::numeric, 'Архитектура', 'Норвегия', 'Берген'),
    ('Исторический центр Кракова',
     'Ансамбль средневекового города, холма Вавель и исторического района Казимеж с площадями, храмами и памятниками разных эпох.',
     'Краков получил городские права в 1257 году и был столицей Польши. Его исторический центр сохраняет городскую планировку, средневековые укрепления, королевскую резиденцию на Вавеле и архитектурные памятники от романского периода до современности.',
     50.061389::numeric, 19.937222::numeric, 'Исторические места', 'Польша', 'Краков'),
    ('Монастырь иеронимитов',
     'Монастырский комплекс в районе Белен у устья реки Тежу, выдающийся памятник португальской архитектуры мануэлино.',
     'Строительство началось в 1502 году по заказу короля Мануэла I. Монастырь был связан с мореплавателями и эпохой географических открытий; его ансамбль включает церковь, клуатр, трапезную и библиотеку.',
     38.697778::numeric, -9.206667::numeric, 'Религиозные сооружения', 'Португалия', 'Лиссабон'),
    ('Петра',
     'Археологический комплекс древнего города, частично построенного, частично высеченного в красных скалах; известен гробницами, храмами и системой водоснабжения.',
     'Петра была столицей набатеев и крупным караванным центром на пересечении торговых путей Аравии, Египта и Сирии. Город процветал в эллинистический и римский периоды; его водохозяйственная система позволяла поддерживать поселение в засушливой местности.',
     30.330560::numeric, 35.443330::numeric, 'Археологические памятники', 'Иордания', 'Вади-Муса'),
    ('Храм Боробудур',
     'Буддийский храмовый комплекс в Центральной Яве, построенный в форме ступенчатой пирамиды с террасами, ступами и рельефами.',
     'Комплекс возведён в VIII–IX веках при династии Шайлендра. После периода использования как буддийского святилища он был заброшен, а в XX веке прошёл масштабную реставрацию при участии ЮНЕСКО.',
     -7.607778::numeric, 110.203861::numeric, 'Религиозные сооружения', 'Индонезия', 'Боробудур'),
    ('Форт Иисус',
     'Португальская крепость на коралловом выступе у побережья Момбасы, построенная для защиты морского порта.',
     'Форт сооружён португальцами в 1593–1596 годах по проекту Джованни Баттисты Кайрати. Он отражает борьбу за контроль над торговыми путями Индийского океана и является хорошо сохранившимся примером португальской военной архитектуры XVI века.',
     -4.062778::numeric, 39.679444::numeric, 'Исторические места', 'Кения', 'Момбаса'),
    ('Исторический город Аюттхая',
     'Руины бывшей столицы Сиамского королевства с храмовыми комплексами, монастырями и башнями-прангами.',
     'Аюттхая основана около 1350 года и стала второй столицей Сиама после Сукхотая. С XIV по XVIII век город был крупным дипломатическим и торговым центром; в XVIII веке он был разрушен бирманскими войсками.',
     14.347780::numeric, 100.560560::numeric, 'Археологические памятники', 'Таиланд', 'Аюттхая'),
    ('Дворцовый комплекс Чхандоккун',
     'Королевский дворцовый ансамбль династии Чосон, в котором официальные и жилые здания объединены с садом и естественным рельефом.',
     'Дворец построен в XV веке по приказу короля Тхэджона как дополнительная резиденция. После разрушения дворцов во время японского вторжения в конце XVI века Чхандоккун был восстановлен первым и на протяжении примерно 250 лет служил главной резиденцией династии.',
     37.578889::numeric, 126.991111::numeric, 'Архитектура', 'Республика Корея', 'Сеул')
) AS v(name, description, history, latitude, longitude, category_name, country_name, city_name)
JOIN categories cat ON cat.name = v.category_name
JOIN countries co ON co.name = v.country_name
JOIN cities ci ON ci.country_id = co.country_id AND ci.name = v.city_name
WHERE NOT EXISTS (
    SELECT 1 FROM attractions a
    WHERE a.name = v.name AND a.city_id = ci.city_id
);


-- Вторая проверенная партия: 10 государств, ранее без достопримечательностей.
-- Описания и координаты сверены с официальными данными UNESCO World Heritage Centre.
INSERT INTO cities (country_id, name)
SELECT co.country_id, v.city_name FROM (VALUES
    ('Перу', 'Агуас-Кальентес'),
    ('Камбоджа', 'Сиемреап'),
    ('Танзания', 'Занзибар'),
    ('Эфиопия', 'Лалибэла'),
    ('Сенегал', 'Горе'),
    ('Хорватия', 'Дубровник'),
    ('Швеция', 'Висбю'),
    ('Финляндия', 'Хельсинки'),
    ('Аргентина', 'Кордова'),
    ('Чили', 'Ханга-Роа')
) AS v(country_name, city_name)
JOIN countries co ON co.name = v.country_name
ON CONFLICT (country_id, name) DO NOTHING;

INSERT INTO attractions
 (name, description, history, latitude, longitude, category_id, city_id)
SELECT v.name, v.description, v.history, v.latitude, v.longitude, cat.category_id, ci.city_id
FROM (VALUES
    ('Исторический заповедник Мачу-Пикчу', 'Археологический комплекс инков в высокогорном тропическом лесу Анд: каменные стены, террасы и лестницы встроены в горный рельеф.', 'Мачу-Пикчу создан в период расцвета империи инков в XV веке. Комплекс объединяет архитектурные сооружения и систему террас; после испанского завоевания он оказался вне основных колониальных маршрутов и получил широкую известность в XX веке.', -13.184934::numeric, -72.533443::numeric, 'Археологические памятники', 'Перу', 'Агуас-Кальентес'),
    ('Ангкор', 'Обширный археологический парк с остатками столиц Кхмерской империи, храмовыми комплексами, водоёмами, Ангкор-Ватом и Байоном.', 'Ангкор был политическим и религиозным центром Кхмерской империи с IX по XV век. Правители расширяли столичный ансамбль, создавая храмы и гидротехнические сооружения.', 13.438889::numeric, 103.867778::numeric, 'Археологические памятники', 'Камбоджа', 'Сиемреап'),
    ('Каменный город Занзибара', 'Исторический прибрежный торговый квартал с плотной застройкой и зданиями, сочетающими африканские, арабские, индийские и европейские влияния.', 'Каменный город развивался как центр торговли Восточной Африки. Более тысячелетия здесь взаимодействовали суахилийские, арабские, индийские и европейские традиции; с XV по XIX век Занзибар играл важную роль в морской торговле.', -6.16306::numeric, 39.18917::numeric, 'Исторические места', 'Танзания', 'Занзибар'),
    ('Скальные церкви в Лалибэле', 'Комплекс из одиннадцати средневековых монолитных церквей, высеченных в скальной породе в горном районе Эфиопии.', 'Создание комплекса связывают с царём Лалибэлой и замыслом устроить в XII–XIII веках «Новый Иерусалим». Церкви остаются важным центром эфиопского христианства, богослужений и паломничества.', 12.033333::numeric, 38.816667::numeric, 'Религиозные сооружения', 'Эфиопия', 'Лалибэла'),
    ('Остров Горе', 'Небольшой остров у Дакара с исторической застройкой, укреплениями и домами торговцев, связанными с трансатлантической работорговлей.', 'С XV по XIX век остров был одним из крупнейших центров работорговли на африканском побережье. Им последовательно управляли португальцы, голландцы, англичане и французы. Застройка свидетельствует о насилии и эксплуатации людей.', 14.66722::numeric, -17.40083::numeric, 'Исторические места', 'Сенегал', 'Горе'),
    ('Старый город Дубровника', 'Исторический город-крепость на Адриатике с каменными стенами, церквями, монастырями, дворцами и фонтанами.', 'С XIII века Дубровник был значимой морской державой Средиземноморья. Землетрясение 1667 года повредило город, но сохранилась значительная часть готических, ренессансных и барочных памятников. После разрушений 1990-х проводилась реставрация.', 42.641417::numeric, 18.108861::numeric, 'Исторические места', 'Хорватия', 'Дубровник'),
    ('Ганзейский город Висбю', 'Средневековый укреплённый торговый город на острове Готланд с городской стеной XIII века, складами и купеческими домами.', 'Висбю возник на месте поселения викингов и в XII–XIV веках стал одним из главных центров Ганзейского союза на Балтике. Сохранившиеся укрепления и торговые здания показывают устройство средневекового портового города.', 57.64167::numeric, 18.29583::numeric, 'Исторические места', 'Швеция', 'Висбю'),
    ('Крепость Суоменлинна', 'Морская крепость на островах у входа в гавань Хельсинки с оборонительными стенами, бастионами и историческими зданиями.', 'Крепость начали строить шведы в 1748 году. В разные периоды она находилась под властью Швеции, Российской империи и независимой Финляндии; ансамбль отражает фортификационную архитектуру XVIII века.', 60.14722::numeric, 24.98722::numeric, 'Архитектура', 'Финляндия', 'Хельсинки'),
    ('Иезуитский квартал и эстасьи Кордовы', 'Ансамбль иезуитского квартала в городе Кордова и пяти сельских поместий с религиозными, учебными и хозяйственными постройками XVII–XVIII веков.', 'Комплекс отражает более чем 150-летний религиозный, социальный и экономический эксперимент Общества Иисуса в Южной Америке. Городской квартал включал церковь, резиденцию иезуитов, университет и колледж; сельские эстасьи объединяли часовни, хозяйственные здания и инженерные системы.', -31.418089::numeric, -64.186639::numeric, 'Исторические места', 'Аргентина', 'Кордова'),
    ('Национальный парк Рапа-Нуи', 'Культурный ландшафт острова Пасхи с церемониальными платформами аху, каменными статуями моаи и следами поселений полинезийского общества.', 'Полинезийское население острова сформировало самобытную традицию монументальной скульптуры и архитектуры. С X по XVI век создавались святилища и устанавливались огромные каменные фигуры моаи.', -27.074403::numeric, -109.365683::numeric, 'Археологические памятники', 'Чили', 'Ханга-Роа')
) AS v(name, description, history, latitude, longitude, category_name, country_name, city_name)
JOIN categories cat ON cat.name = v.category_name
JOIN countries co ON co.name = v.country_name
JOIN cities ci ON ci.country_id = co.country_id AND ci.name = v.city_name
WHERE NOT EXISTS (SELECT 1 FROM attractions a WHERE a.name = v.name AND a.city_id = ci.city_id);


-- Партия 03: ещё 10 городов и локальностей в ранее не представленных странах.
INSERT INTO cities (country_id, name)
SELECT co.country_id, v.city_name
FROM (VALUES
    ('Узбекистан', 'Самарканд'),
    ('Непал', 'Катманду'),
    ('Шри-Ланка', 'Сигирия'),
    ('Тунис', 'Кайруан'),
    ('Ливан', 'Баальбек'),
    ('Боливия', 'Потоси'),
    ('Гватемала', 'Тикаль'),
    ('Бельгия', 'Брюгге'),
    ('Дания', 'Йеллинг'),
    ('Лаос', 'Луангпхабанг')
) AS v(country_name, city_name)
JOIN countries co ON co.name = v.country_name
ON CONFLICT (country_id, name) DO NOTHING;

-- Партия 03: достопримечательности; повторный запуск не создаёт дубликаты.
INSERT INTO attractions
 (name, description, history, latitude, longitude, category_id, city_id)
SELECT v.name, v.description, v.history, v.latitude, v.longitude, cat.category_id, ci.city_id
FROM (VALUES
    ('Самарканд — перекрёсток культур', 'Исторический город на Великом шёлковом пути с ансамблями медресе, мечетей, мавзолеев и обсерваторией Улугбека.', 'Самарканд известен как Афрасиаб с VII века до н. э. Наивысшего расцвета город достиг в XIV–XV веках при Тимуридах, когда стал столицей государства Тимура и крупным центром науки, торговли и архитектуры.', 39.650000::numeric, 66.966667::numeric, 'Исторические места', 'Узбекистан', 'Самарканд'),
    ('Площадь Дурбар Хануман-Дхока', 'Историческая площадь Катманду с королевским дворцовым комплексом, храмами и общественными пространствами, входящая в объект Всемирного наследия «Долина Катманду».', 'Площадь была центром королевской власти и городской жизни Катманду. Дворцовые и храмовые сооружения формировались в течение нескольких столетий, особенно в период правления династий Малла и Шах.', 27.703889::numeric, 85.308333::numeric, 'Исторические места', 'Непал', 'Катманду'),
    ('Древний город Сигирия', 'Археологический комплекс на вершине массивной скалы с остатками дворца-крепости, садами, водными сооружениями и настенными росписями.', 'В V веке король Кашьяпа превратил скалу Сигирия в укреплённую резиденцию. После переноса столицы комплекс использовался как буддийский монастырь и сохранил следы древнего градостроительства и инженерии.', 7.950000::numeric, 80.750000::numeric, 'Археологические памятники', 'Шри-Ланка', 'Сигирия'),
    ('Исторический город Кайруан', 'Исторический центр одного из важнейших религиозных и культурных городов Магриба, включающий медину, мечети, мавзолей и водные сооружения Аглабидов.', 'Кайруан был основан в 670 году и стал столицей Ифрикии при Аглабидах. В IX веке город превратился в крупный центр исламской учёности, религиозной жизни и архитектуры Северной Африки.', 35.677778::numeric, 10.100000::numeric, 'Исторические места', 'Тунис', 'Кайруан'),
    ('Храмовый комплекс Баальбека', 'Монументальный археологический ансамбль римских храмов Юпитера, Вакха и Венеры, расположенный на месте более древнего финикийского святилища.', 'В эллинистическую эпоху город был известен как Гелиополь. При Римской империи, особенно со I века до н. э. по III век н. э., здесь сформировался один из крупнейших храмовых комплексов античного мира.', 34.006667::numeric, 36.204167::numeric, 'Археологические памятники', 'Ливан', 'Баальбек'),
    ('Исторический город Потоси', 'Колониальный горный город в Андах, связанный с серебряными рудниками Серро-Рико, монетным двором, церквями и системой гидротехнических сооружений.', 'После открытия богатых серебряных залежей в XVI веке Потоси быстро вырос и стал одним из крупнейших промышленных центров мира своего времени. В 1572 году город получил статус имперского, а добыча серебра определила его экономическое и архитектурное развитие.', -19.599112::numeric, -65.749813::numeric, 'Исторические места', 'Боливия', 'Потоси'),
    ('Национальный парк Тикаль', 'Археологический комплекс в тропическом лесу Петена с храмами, дворцами, церемониальными площадями и остатками жилых кварталов цивилизации майя.', 'Тикаль был одним из крупнейших политических и культурных центров майя. Город развивался с VI века до н. э. и достиг значительного расцвета в классический период; надписи и стелы фиксируют историю правителей вплоть до IX века н. э.', 17.216667::numeric, -89.616667::numeric, 'Археологические памятники', 'Гватемала', 'Тикаль'),
    ('Исторический центр Брюгге', 'Средневековый городской ансамбль с исторической уличной сетью, каналами, площадями, готическими зданиями и сохранившейся городской застройкой.', 'В Средние века Брюгге был крупным торговым и культурным центром Европы. Его архитектура отражает развитие кирпичной готики, международных торговых связей и художественных традиций Фландрии.', 51.208910::numeric, 3.225270::numeric, 'Исторические места', 'Бельгия', 'Брюгге'),
    ('Йеллингские курганы, рунные камни и церковь', 'Комплекс памятников эпохи викингов, объединяющий два кургана, два рунических камня и церковь, отражающие переход Дании от язычества к христианству.', 'В X веке Йеллинг был королевской резиденцией Горма Старого и его сына Харальда Синезубого. Большой рунический камень Харальда связывает объединение Дании с распространением христианства; комплекс считается ключевым памятником ранней датской государственности.', 55.756389::numeric, 9.420000::numeric, 'Археологические памятники', 'Дания', 'Йеллинг'),
    ('Исторический город Луангпхабанг', 'Хорошо сохранившийся городской ансамбль на полуострове между Меконгом и Нам-Кханом, сочетающий традиционную лаосскую архитектуру, буддийские монастыри и колониальную застройку.', 'С XIV по XVI век Луангпхабанг, тогда известный как Сиенг-Тхонг, был столицей королевства Лансанг. Город сохранял религиозное и культурное значение, а в XIX–XX веках его облик дополнился зданиями европейского колониального периода.', 19.888890::numeric, 102.133330::numeric, 'Архитектура', 'Лаос', 'Луангпхабанг')
) AS v(name, description, history, latitude, longitude, category_name, country_name, city_name)
JOIN categories cat ON cat.name = v.category_name
JOIN countries co ON co.name = v.country_name
JOIN cities ci ON ci.country_id = co.country_id AND ci.name = v.city_name
WHERE NOT EXISTS (SELECT 1 FROM attractions a WHERE a.name = v.name AND a.city_id = ci.city_id);


-- Партия 04: ещё 10 городов и локальностей в ранее не представленных странах.
INSERT INTO cities (country_id, name)
SELECT co.country_id, v.city_name
FROM (VALUES
    ('Ирландия', 'Донор'), ('Румыния', 'Сигишоара'), ('Болгария', 'Рильский монастырь'),
    ('Грузия', 'Мцхета'), ('Армения', 'Ахпат'), ('Азербайджан', 'Баку'),
    ('Сербия', 'Студеница'), ('Албания', 'Бутринт'), ('Кипр', 'Пафос'), ('Мальта', 'Валлетта')
) AS v(country_name, city_name)
JOIN countries co ON co.name = v.country_name
ON CONFLICT (country_id, name) DO NOTHING;

-- Партия 04: достопримечательности; повторный запуск не создаёт дубликаты.
INSERT INTO attractions
 (name, description, history, latitude, longitude, category_id, city_id)
SELECT v.name, v.description, v.history, v.latitude, v.longitude, cat.category_id, ci.city_id
FROM (VALUES
('Археологический ансамбль Бру-на-Бойн','Доисторический ритуально-погребальный ландшафт в излучине реки Бойн, включающий крупные проходные гробницы Ньюгрейндж, Ноут и Даут и множество сопутствующих памятников.','Основные памятники комплекса были созданы в период неолита, около пяти тысяч лет назад. Их масштаб, инженерные решения и мегалитическое искусство свидетельствуют о сложной общественной и религиозной организации древних общин Ирландии.',53.694694::numeric,-6.475500::numeric,'Археологические памятники','Ирландия','Донор'),
('Исторический центр Сигишоары','Хорошо сохранившийся средневековый укреплённый город с цитаделью, башнями ремесленных гильдий, церквями и плотной исторической застройкой.','Сигишоара развивалась как саксонское торговое и ремесленное поселение Трансильвании с XII века. Её укрепления и башни отражают устройство средневекового города и роль немецких ремесленных общин в регионе.',46.217778::numeric,24.792222::numeric,'Исторические места','Румыния','Сигишоара'),
('Рильский монастырь','Крупный православный монастырский комплекс в Рильских горах, известный аркадными галереями, церковью Рождества Богородицы, фресками и музейными собраниями.','Монастырь основан в X веке святым Иоанном Рильским. Он стал важным духовным и культурным центром средневековой Болгарии; после пожара в начале XIX века комплекс был восстановлен в 1834–1862 годах и стал символом болгарского национального Возрождения.',42.133297::numeric,23.340186::numeric,'Религиозные сооружения','Болгария','Рильский монастырь'),
('Исторические памятники Мцхеты','Комплекс средневековых христианских памятников древней столицы Грузии: собор Светицховели, монастырь Самтавро и монастырь Джвари.','Мцхета была столицей восточногрузинского царства Картли с III века до н. э. до V века н. э. В 337 году христианство было провозглашено государственной религией; соборные и монастырские ансамбли отражают последующее развитие грузинской церковной архитектуры.',41.842833::numeric,44.720944::numeric,'Религиозные сооружения','Грузия','Мцхета'),
('Монастырь Ахпат','Средневековый армянский монастырский ансамбль с церквями, притворами, колокольней и другими сооружениями, гармонично включёнными в горный ландшафт Лори.','Монастырь был основан в X веке при царе Ашоте III и развивался в период расцвета династии Кюрикидов в X–XIII веках. Ахпат был важным центром богословия, образования, переписки и иллюминирования рукописей.',41.093828::numeric,44.712394::numeric,'Религиозные сооружения','Армения','Ахпат'),
('Старый город Баку — Ичеришехер','Исторический внутристенный город с дворцом Ширваншахов, Девичьей башней, мечетями, караван-сараями, банями и фрагментами оборонительных стен.','Ичеришехер сохраняет следы нескольких культурных эпох и значительную часть оборонительных стен XII века. Девичья башня включает более ранние строительные слои, а дворцовый комплекс Ширваншахов формировался в XII–XV веках.',40.366667::numeric,49.833333::numeric,'Архитектура','Азербайджан','Баку'),
('Монастырь Студеница','Православный монастырский комплекс с церковью Богородицы, Королевской церковью и ценными циклами византийской фресковой живописи XIII–XIV веков.','Монастырь основан в конце XII века Стефаном Неманей, основателем средневекового сербского государства. Он стал важнейшим духовным центром Сербии; здесь связаны память о династии Неманичей и становление самостоятельной Сербской православной церкви.',43.486528::numeric,20.531667::numeric,'Религиозные сооружения','Сербия','Студеница'),
('Археологический комплекс Бутринт','Археологический парк на юге Албании с остатками греческого города, римских общественных зданий, раннехристианской базилики, византийских сооружений и венецианских укреплений.','Бутринт был заселён с доисторических времён, затем стал греческой колонией, римским городом и епископским центром. После периода византийского и венецианского влияния поселение постепенно опустело в позднем Средневековье.',39.745732::numeric,20.020950::numeric,'Археологические памятники','Албания','Бутринт'),
('Археологический комплекс Неа-Пафоса','Археологическая зона Като-Пафоса с руинами античных вилл, дворцов, театра, крепости и знаменитыми мозаичными полами римских домов.','Пафос был важным центром культа Афродиты и одним из значимых городов эллинистического и римского Кипра. Археологические памятники отражают развитие города от античности до позднеримского периода.',34.758333::numeric,32.405556::numeric,'Археологические памятники','Кипр','Пафос'),
('Город Валлетта','Укреплённый ренессансный город на полуострове между двумя естественными гаванями, с регулярной уличной сетью, бастионами, дворцами, церквями и общественными зданиями.','Валлетта была основана в 1566 году после Великой осады Мальты 1565 года и названа в честь великого магистра Жана Паризо де ла Валетта. Орден госпитальеров создавал город как целостный оборонительный и административный ансамбль позднего Возрождения.',35.900560::numeric,14.514440::numeric,'Архитектура','Мальта','Валлетта')
) AS v(name, description, history, latitude, longitude, category_name, country_name, city_name)
JOIN categories cat ON cat.name = v.category_name
JOIN countries co ON co.name = v.country_name
JOIN cities ci ON ci.country_id = co.country_id AND ci.name = v.city_name
WHERE NOT EXISTS (SELECT 1 FROM attractions a WHERE a.name = v.name AND a.city_id = ci.city_id);


-- Партия 05: 10 локальностей и достопримечательностей в ранее не представленных странах.
INSERT INTO cities (country_id,name)
SELECT co.country_id,v.city_name FROM (VALUES
('Алжир','Типаза'),('Ангола','Мбанза-Конго'),('Бенин','Абомей'),('Ботсвана','Цодило'),('Буркина-Фасо','Лоропени'),('Кабо-Верде','Сидаде-Велья'),('Камерун','Южный регион'),('Чад','Эннеди'),('Кот-д’Ивуар','Гран-Бассам'),('Демократическая Республика Конго','Гома')
) v(country_name,city_name) JOIN countries co ON co.name=v.country_name
ON CONFLICT(country_id,name) DO NOTHING;
INSERT INTO attractions(name,description,history,latitude,longitude,category_id,city_id)
SELECT v.name,v.description,v.history,v.latitude,v.longitude,cat.category_id,ci.city_id FROM (VALUES
('Археологический парк Типаза','Археологический комплекс на средиземноморском побережье Алжира с финикийскими, римскими, раннехристианскими и византийскими памятниками.','Типаза возникла как финикийское поселение, затем стала римской колонией. Руины включают форумы, термы, театр, базилики и некрополи; объект ЮНЕСКО с 1982 года.',36.593972::numeric,2.443389::numeric,'Археологические памятники','Алжир','Типаза'),
('Исторический центр Мбанза-Конго','Историческая территория бывшей столицы Королевства Конго на плато в северной части Анголы.','С XIV по XIX век Мбанза-Конго был политическим и духовным центром Королевства Конго. Город отражает местные традиции и изменения после прибытия португальцев; объект ЮНЕСКО с 2017 года.',-6.267000::numeric,14.240000::numeric,'Исторические места','Ангола','Мбанза-Конго'),
('Королевские дворцы Абомея','Комплекс дворцовых сооружений бывшего королевства Дагомея, включающий дворцы правителей, ритуальные пространства и исторические рельефы.','Абомей был столицей Дагомеи с XVII до конца XIX века. Дворцы последовательно строились правителями династии; объект ЮНЕСКО с 1985 года.',7.185000::numeric,1.991000::numeric,'Исторические места','Бенин','Абомей'),
('Культурный ландшафт Цодило','Группа холмов в пустыне Калахари с наскальными рисунками и археологическими свидетельствами длительного присутствия человека.','В Цодило сосредоточены тысячи наскальных изображений, созданных на протяжении многих тысячелетий. Место имеет духовное значение для местных общин; объект ЮНЕСКО с 2001 года.',-18.758000::numeric,21.750000::numeric,'Археологические памятники','Ботсвана','Цодило'),
('Руины Лоропени','Каменные руины укреплённого поселения в юго-западной части Буркина-Фасо, окружённые массивными стенами из латерита.','Комплекс связан с историей транссахарской торговли золотом. Возраст отдельных элементов оценивается в несколько столетий; объект ЮНЕСКО с 2009 года.',10.296000::numeric,-3.535000::numeric,'Исторические места','Буркина-Фасо','Лоропени'),
('Исторический центр Сидаде-Велья','Исторический ансамбль бывшего португальского поселения Рибейра-Гранде на острове Сантьягу, включающий крепость, церкви и городскую застройку.','Основанное в XV веке поселение стало важным пунктом португальской морской экспансии и трансатлантической торговли; объект ЮНЕСКО с 2009 года.',14.916700::numeric,-23.605000::numeric,'Исторические места','Кабо-Верде','Сидаде-Велья'),
('Заповедник фауны Джа','Крупный массив влажных тропических лесов бассейна Конго, охраняющий экосистемы и местообитания редких животных.','Заповедник сохраняет один из крупнейших непрерывных массивов тропического леса Африки и входит в Список всемирного наследия ЮНЕСКО с 1987 года.',3.000000::numeric,12.800000::numeric,'Природные объекты','Камерун','Южный регион'),
('Природно-культурный ландшафт массива Эннеди','Обширный пустынный горный массив в северо-восточном Чаде с песчаниковыми образованиями, каньонами, природными арками и наскальным искусством.','Эннеди содержит свидетельства многотысячелетней истории присутствия человека в Сахаре. Объект включён в Список всемирного наследия ЮНЕСКО в 2016 году.',17.000000::numeric,22.000000::numeric,'Природные объекты','Чад','Эннеди'),
('Исторический город Гран-Бассам','Прибрежный исторический город с колониальной административной застройкой, торговыми кварталами и традиционными поселениями народа нзима.','Гран-Бассам был важным колониальным портом и административным центром Французской Кот-д’Ивуар в конце XIX — начале XX века; объект ЮНЕСКО с 2012 года.',5.200000::numeric,-3.738000::numeric,'Исторические места','Кот-д’Ивуар','Гран-Бассам'),
('Национальный парк Вирунга','Один из старейших национальных парков Африки: вулканические ландшафты, горные леса, саванны и местообитания горных горилл.','Парк основан в 1925 году как Национальный парк Альберта. С 1979 года входит в Список всемирного наследия ЮНЕСКО и также включён в список объектов под угрозой.',-1.400000::numeric,29.500000::numeric,'Природные объекты','Демократическая Республика Конго','Гома')
) v(name,description,history,latitude,longitude,category_name,country_name,city_name)
JOIN categories cat ON cat.name=v.category_name JOIN countries co ON co.name=v.country_name
JOIN cities ci ON ci.country_id=co.country_id AND ci.name=v.city_name
WHERE NOT EXISTS(SELECT 1 FROM attractions a WHERE a.name=v.name AND a.city_id=ci.city_id);


-- Партия 06: 10 локальностей и достопримечательностей в ранее не представленных странах.
INSERT INTO cities (country_id, name)
SELECT co.country_id, v.city_name
FROM (VALUES
('Доминиканская Республика','Санто-Доминго'),('Эквадор','Кито'),('Сальвадор','Сан-Хуан-Опико'),
('Эстония','Таллин'),('Фиджи','Левука'),('Гамбия','Остров Джеймс'),('Гаити','Милот'),
('Гондурас','Копан-Руинас'),('Венгрия','Будапешт'),('Исландия','Тингведлир')
) AS v(country_name,city_name)
JOIN countries co ON co.name=v.country_name
ON CONFLICT(country_id,name) DO NOTHING;

INSERT INTO attractions(name,description,history,latitude,longitude,category_id,city_id)
SELECT v.name,v.description,v.history,v.latitude,v.longitude,cat.category_id,ci.city_id
FROM (VALUES
('Колониальный город Санто-Доминго','Исторический центр столицы Доминиканской Республики с регулярной уличной сетью, крепостными сооружениями, собором и гражданскими зданиями раннего колониального периода.','Санто-Доминго был основан в конце XV века и стал одним из первых постоянных европейских поселений в Америке. Городская планировка и памятники XVI века повлияли на развитие колониальных городов Нового Света; объект включён в Список всемирного наследия ЮНЕСКО в 1990 году.',18.472394::numeric,-69.885841::numeric,'Исторические места','Доминиканская Республика','Санто-Доминго'),
('Исторический центр Кито','Колониальный исторический центр столицы Эквадора с монастырями, церквями, площадями и зданиями, сочетающими европейские и местные художественные традиции.','Кито был основан испанцами в XVI веке на месте поселения инков. Его архитектура отражает развитие барочной школы Кито, в которой соединились испанские, итальянские, мавританские, фламандские и коренные художественные влияния; объект ЮНЕСКО с 1978 года.',-0.220000::numeric,-78.512083::numeric,'Архитектура','Эквадор','Кито'),
('Археологический памятник Хойя-де-Серен','Археологический памятник древнего сельского поселения майя, погребённого под вулканическим пеплом и сохранившего жилые и хозяйственные постройки.','Поселение было погребено извержением вулкана Лома-Кальдера примерно в VI веке. Слой пепла сохранил повседневную среду обитания, сельскохозяйственные сооружения и предметы быта; объект включён в Список всемирного наследия ЮНЕСКО в 1993 году.',13.827500::numeric,-89.369167::numeric,'Археологические памятники','Сальвадор','Сан-Хуан-Опико'),
('Исторический центр Таллина','Средневековый Старый город Таллина с верхним и нижним городом, крепостными стенами, башнями, церквями и сохранившейся исторической уличной сетью.','Таллин развивался как важный торговый центр Балтийского региона и участник Ганзейского союза. Средневековая планировка и значительная часть исторической застройки сохранились до наших дней; объект ЮНЕСКО с 1997 года.',59.437000::numeric,24.740000::numeric,'Исторические места','Эстония','Таллин'),
('Исторический портовый город Левука','Исторический портовый город на острове Овалау с деревянной и каменной застройкой XIX века, портовыми сооружениями и общественными зданиями.','Левука развивалась как торговый и административный центр Фиджи в период европейского присутствия в XIX веке. Город сохраняет характерную планировку раннего колониального порта Тихого океана; объект ЮНЕСКО с 2013 года.',-17.683378::numeric,178.834533::numeric,'Исторические места','Фиджи','Левука'),
('Остров Джеймс и связанные с ним памятники','Исторический комплекс на реке Гамбия, включающий руины форта на острове Джеймс и связанные с европейской торговлей и работорговлей поселения, батареи и укрепления.','Остров был стратегическим пунктом контроля речного торгового пути. Комплекс свидетельствует о контактах Африки и Европы с XV по XX век и непосредственно связан с историей трансатлантической работорговли и её отмены; объект ЮНЕСКО с 2003 года.',13.317642::numeric,-16.361353::numeric,'Исторические места','Гамбия','Остров Джеймс'),
('Национальный исторический парк — Цитадель, Сан-Суси и Рамьер','Исторический ансамбль на севере Гаити, включающий горную крепость Цитадель Лаферьер, дворцовые руины Сан-Суси и укрепления Рамьер.','Комплекс связан с созданием независимого гаитянского государства после революции. Цитадель строилась в начале XIX века для обороны страны, а дворец Сан-Суси служил резиденцией короля Анри Кристофа; объект ЮНЕСКО с 1982 года.',19.573025::numeric,-72.234268::numeric,'Исторические места','Гаити','Милот'),
('Археологический комплекс Копан','Археологический центр цивилизации майя с акрополем, площадями, храмами, алтарями и монументальной Иероглифической лестницей.','Копан был политическим, общественным и религиозным центром долины с периода классической цивилизации майя. Город достиг расцвета в III–IX веках; его скульптура и иероглифические надписи имеют исключительное историческое значение. Объект ЮНЕСКО с 1980 года.',14.838000::numeric,-89.142000::numeric,'Археологические памятники','Гондурас','Копан-Руинас'),
('Исторический ландшафт Будапешта — берега Дуная, Будайская крепость и проспект Андраши','Городской ансамбль, объединяющий панораму берегов Дуная, исторический квартал Буды, мосты, общественные здания и проспект Андраши с подземной железной дорогой.','Буда и Пешт развивались как отдельные исторические города по берегам Дуная, а затем объединились в столицу Венгрии. Комплекс отражает важные этапы развития городской архитектуры и европейского градостроительства; объект ЮНЕСКО с 1987 года.',47.497047::numeric,19.042883::numeric,'Архитектура','Венгрия','Будапешт'),
('Национальный парк Тингведлир','Культурный ландшафт в рифтовой долине Исландии с местом древнего народного собрания Альтинга, историческими остатками поселения, озером и выразительными геологическими разломами.','Альтинг был основан в Тингведлире около 930 года и собирался здесь до конца XVIII века. Место стало важным символом исландской государственности; ландшафт также демонстрирует процессы расхождения тектонических плит. Объект включён в Список всемирного наследия ЮНЕСКО в 2004 году.',64.253806::numeric,-21.037250::numeric,'Природные объекты','Исландия','Тингведлир')
) AS v(name,description,history,latitude,longitude,category_name,country_name,city_name)
JOIN categories cat ON cat.name=v.category_name
JOIN countries co ON co.name=v.country_name
JOIN cities ci ON ci.country_id=co.country_id AND ci.name=v.city_name
WHERE NOT EXISTS(SELECT 1 FROM attractions a WHERE a.name=v.name AND a.city_id=ci.city_id);



-- Партия 07: 10 локальностей и объектов всемирного наследия в ранее не представленных странах.
INSERT INTO cities (country_id, name)
SELECT co.country_id, v.city_name
FROM (VALUES
('Босния и Герцеговина','Мостар'),
('Колумбия','Картахена'),
('Коста-Рика','Остров Кокос'),
('Куба','Гавана'),
('Литва','Вильнюс'),
('Люксембург','Люксембург'),
('Мадагаскар','Амбохиманга-Рова'),
('Намибия','Твайфелфонтейн'),
('Нигерия','Ошогбо'),
('Новая Зеландия','Тонгариро')
) AS v(country_name, city_name)
JOIN countries co ON co.name = v.country_name
ON CONFLICT (country_id, name) DO NOTHING;

INSERT INTO attractions
 (name, description, history, latitude, longitude, category_id, city_id)
SELECT v.name, v.description, v.history, v.latitude, v.longitude, cat.category_id, ci.city_id
FROM (VALUES
('Район Старого моста исторического города Мостар','Исторический ансамбль османского города в долине реки Неретвы, включающий Старый мост, традиционную городскую застройку и прилегающие общественные пространства.','Мостар развивался в XV–XVI веках как османский пограничный город. Старый мост, построенный в XVI веке, был разрушен в ходе конфликта 1990-х годов и восстановлен в 2004 году при международном сотрудничестве. Объект включён в Список всемирного наследия ЮНЕСКО в 2005 году.',43.337306::numeric,17.815000::numeric,'Исторические места','Босния и Герцеговина','Мостар'),
('Порт, крепости и группа памятников Картахены','Укреплённый исторический портовый город на карибском побережье Колумбии с крепостными стенами, бастионами, замком Сан-Фелипе-де-Барахас и исторической городской застройкой.','Картахена была основана испанцами в 1533 году и стала одним из важнейших портов Испанской Америки. Её оборонительная система формировалась в XVI–XVIII веках для защиты порта и торговых путей; объект ЮНЕСКО с 1984 года.',10.416667::numeric,-75.533333::numeric,'Исторические места','Колумбия','Картахена'),
('Национальный парк острова Кокос','Островной природный комплекс в восточной части Тихого океана с тропическими лесами, водопадами и исключительным морским биоразнообразием.','Остров Кокос известен как важная территория сохранения морских экосистем и миграционных маршрутов крупных пелагических видов. Национальный парк включён в Список всемирного наследия ЮНЕСКО в 1997 году; в 2002 году границы объекта были расширены.',5.533333::numeric,-87.066667::numeric,'Природные объекты','Коста-Рика','Остров Кокос'),
('Старая Гавана и система укреплений','Исторический центр Гаваны с пятью основными площадями, барочными и неоклассическими зданиями, узкими улицами и системой колониальных крепостей у входа в гавань.','Гавана была основана испанцами в 1519 году и стала важнейшим портом Карибского региона. С XVI по XIX век вокруг гавани создавалась разветвлённая система оборонительных сооружений; объект ЮНЕСКО с 1982 года.',23.136524::numeric,-82.359056::numeric,'Исторические места','Куба','Гавана'),
('Исторический центр Вильнюса','Средневековое ядро литовской столицы с замковыми территориями, извилистой уличной сетью и ансамблями готической, ренессансной, барочной и классической архитектуры.','Вильнюс стал политическим центром Великого княжества Литовского и к XIV веку приобрёл значение столицы. Исторический центр сохранил средневековую планировку и разнообразную архитектуру; объект ЮНЕСКО с 1994 года.',54.686670::numeric,25.293060::numeric,'Архитектура','Литва','Вильнюс'),
('Старые кварталы и укрепления города Люксембурга','Исторический городской ансамбль на скалистом плато с остатками бастионов, казематами, мостами и кварталами старого города.','Стратегическое положение Люксембурга способствовало созданию одной из наиболее значительных крепостей Европы. Укрепления развивались с X века и демонтировались после Лондонского договора 1867 года; сохранившиеся кварталы и фортификационные сооружения включены в список ЮНЕСКО в 1994 году.',49.610000::numeric,6.133330::numeric,'Исторические места','Люксембург','Люксембург'),
('Королевский холм Амбохиманга','Королевский город, место захоронений и ансамбль священных мест на холме в центральной части Мадагаскара.','Амбохиманга связан с формированием малагасийской государственности и династией, объединившей значительную часть острова. На протяжении нескольких столетий холм сохранял духовное и политическое значение; объект ЮНЕСКО с 2001 года.',-18.759170::numeric,47.562780::numeric,'Исторические места','Мадагаскар','Амбохиманга-Рова'),
('Твайфелфонтейн или /Ui-//aes','Археологический ландшафт в засушливом регионе Намибии с многочисленными петроглифами и наскальными рисунками, созданными общинами охотников-собирателей.','Наскальное искусство Твайфелфонтейна отражает ритуальные практики и хозяйственную жизнь древних общин юга Африки на протяжении как минимум двух тысячелетий. Объект включён в Список всемирного наследия ЮНЕСКО в 2007 году.',-20.594770::numeric,14.375097::numeric,'Археологические памятники','Намибия','Твайфелфонтейн'),
('Священная роща Осун-Осогбо','Священная лесная территория на берегу реки Осун с храмами, святилищами, скульптурами и произведениями искусства, посвящёнными божествам йоруба.','Роща связана с традиционной религией йоруба и почитанием богини Осун. Она сохраняет культурные практики, ритуалы и природный ландшафт, редкий для региона; объект ЮНЕСКО с 2005 года.',7.755560::numeric,4.552220::numeric,'Природные объекты','Нигерия','Ошогбо'),
('Национальный парк Тонгариро','Вулканический ландшафт Северного острова Новой Зеландии с активными вулканами, кратерными озёрами и местами духовного значения для маори.','Тонгариро стал первым объектом, включённым в список ЮНЕСКО с учётом культурных ценностей коренного народа и природных характеристик территории. В 1993 году он получил статус культурного ландшафта; природный статус был присвоен в 1990 году.',-39.277094::numeric,175.568633::numeric,'Природные объекты','Новая Зеландия','Тонгариро')
) AS v(name, description, history, latitude, longitude, category_name, country_name, city_name)
JOIN categories cat ON cat.name = v.category_name
JOIN countries co ON co.name = v.country_name
JOIN cities ci ON ci.country_id = co.country_id AND ci.name = v.city_name
WHERE NOT EXISTS (
    SELECT 1 FROM attractions a
    WHERE a.name = v.name AND a.city_id = ci.city_id
);


SELECT count(*) AS seeded_attractions FROM attractions;


-- Партия 08: 10 локальностей и объектов всемирного наследия в ранее не представленных странах.
INSERT INTO cities (country_id, name)
SELECT co.country_id, v.city_name
FROM (VALUES
('Афганистан','Джам'),
('Бахрейн','Калат-аль-Бахрейн'),
('Бангладеш','Багерхат'),
('Беларусь','Мир'),
('Белиз','Голубая дыра'),
('Барбадос','Бриджтаун'),
('Габон','Национальный парк Лопе'),
('Гана','Кумаси'),
('Мали','Тимбукту'),
('Мозамбик','Остров Мозамбик')
) AS v(country_name, city_name)
JOIN countries co ON co.name = v.country_name
ON CONFLICT (country_id, name) DO NOTHING;

INSERT INTO attractions
 (name, description, history, latitude, longitude, category_id, city_id)
SELECT v.name, v.description, v.history, v.latitude, v.longitude, cat.category_id, ci.city_id
FROM (VALUES
('Минарет Джам и археологические остатки','Высокий кирпичный минарет XII века в долине реки Хари, окружённый археологическими остатками средневекового поселения Гуридов.','Минарет был возведён в период расцвета Гуридской державы в XII веке и известен сложной кирпичной кладкой, геометрическим орнаментом и куфическими надписями. Вместе с археологическими остатками он включён в Список всемирного наследия ЮНЕСКО в 2002 году.',36.396556::numeric,64.516056::numeric,'Археологические памятники','Афганистан','Джам'),
('Калат-аль-Бахрейн — древняя гавань и столица Дильмуна','Многослойный археологический холм с остатками жилых, общественных, торговых, религиозных и оборонительных сооружений, включая португальский форт на вершине.','Археологические слои свидетельствуют о непрерывном заселении места примерно с 2300 года до н. э. до XVI века н. э. Поселение было важным портом и столицей древнего Дильмуна; объект включён в Список всемирного наследия ЮНЕСКО в 2005 году.',26.234442::numeric,50.518331::numeric,'Археологические памятники','Бахрейн','Калат-аль-Бахрейн'),
('Исторический город мечетей Багерхат','Средневековый город на юго-западе Бангладеш, известный многочисленными кирпичными мечетями, мавзолеями, водоёмами и остатками городской инфраструктуры.','Город, ранее известный как Халифатабад, был основан в XV веке военачальником Улуг-ханом Джаханом. Его планировка и монументальная исламская архитектура отражают развитие региона в период Бенгальского султаната; объект включён в Список всемирного наследия ЮНЕСКО в 1985 году.',22.666670::numeric,89.800000::numeric,'Исторические места','Бангладеш','Багерхат'),
('Мирский замковый комплекс','Замок с оборонительными башнями и внутренним двором, сочетающий готические, ренессансные и барочные архитектурные элементы.','Строительство замка началось в конце XV века. Позднее комплекс расширяли и перестраивали; после периода запустения и повреждений в наполеоновскую эпоху его восстановили в конце XIX века. Объект включён в Список всемирного наследия ЮНЕСКО в 2000 году.',53.451083::numeric,26.472722::numeric,'Архитектура','Беларусь','Мир'),
('Барьерный риф Белиза — морская охраняемая система','Крупнейшая в Северном полушарии система барьерных рифов, атоллов, песчаных островов, мангровых лесов, лагун и эстуариев.','Система включает семь охраняемых участков и служит местом обитания морских черепах, ламантинов, американских крокодилов и множества видов рифовых организмов. Объект был включён в Список всемирного наследия ЮНЕСКО в 1996 году; в 2018 году его исключили из Списка всемирного наследия под угрозой.',17.315986::numeric,-87.534697::numeric,'Природные объекты','Белиз','Голубая дыра'),
('Исторический Бриджтаун и его гарнизон','Исторический портовый город с извилистой уличной сетью, колониальной застройкой XVII–XIX веков и прилегающим военным гарнизоном.','Бриджтаун был одним из ранних укреплённых портов британской Атлантики и важным узлом торговли в Карибском регионе. Городская планировка и здания отражают развитие британской колониальной архитектуры и морской торговли; объект включён в Список всемирного наследия ЮНЕСКО в 2011 году.',13.096667::numeric,-59.613889::numeric,'Исторические места','Барбадос','Бриджтаун'),
('Экосистема и реликтовый культурный ландшафт Лопе-Оканда','Обширная природная территория Габона, объединяющая тропические леса, саванны, речные долины и археологические свидетельства древнего присутствия человека.','Ландшафт отражает длительное взаимодействие природных экосистем и человеческой деятельности в Центральной Африке. Археологические находки свидетельствуют о миграциях и использовании территории в разные исторические периоды; объект включён в Список всемирного наследия ЮНЕСКО в 2007 году.',0.500000::numeric,11.500000::numeric,'Природные объекты','Габон','Национальный парк Лопе'),
('Традиционные здания Ашанти','Группа традиционных святилищ и жилых сооружений народа ашанти, построенных из дерева, бамбука и глиняной штукатурки и украшенных рельефными орнаментами.','Здания являются последними материальными свидетельствами цивилизации ашанти, достигшей расцвета в XVIII веке. Комплекс включает десять традиционных сооружений, большинство из которых расположено к северо-востоку от Кумаси; объект включён в Список всемирного наследия ЮНЕСКО в 1980 году.',6.401111::numeric,-1.625833::numeric,'Архитектура','Гана','Кумаси'),
('Тимбукту','Исторический город Сахеля с тремя знаменитыми мечетями — Джингеребер, Санкоре и Сиди-Яхья, а также традиционными кварталами и мавзолеями.','В XV–XVI веках Тимбукту был крупным интеллектуальным и духовным центром исламской Африки, известным университетом Санкоре, медресе и торговлей рукописями. Город включён в Список всемирного наследия ЮНЕСКО в 1988 году и с 2012 года находится в Списке всемирного наследия под угрозой.',16.773333::numeric,-2.999444::numeric,'Исторические места','Мали','Тимбукту'),
('Остров Мозамбик','Исторический островной город с каменной и известковой застройкой, традиционными домами макути, крепостями и религиозными сооружениями.','Остров был важным пунктом торговли и мореплавания в Индийском океане с X века, а с XVI века стал португальским торговым постом на пути в Индию. Архитектурный ансамбль отражает взаимодействие африканских, суахилийских, арабских, персидских, индийских и европейских традиций; объект включён в Список всемирного наследия ЮНЕСКО в 1991 году.',-15.034170::numeric,40.735830::numeric,'Архитектура','Мозамбик','Остров Мозамбик')
) AS v(name, description, history, latitude, longitude, category_name, country_name, city_name)
JOIN categories cat ON cat.name = v.category_name
JOIN countries co ON co.name = v.country_name
JOIN cities ci ON ci.country_id = co.country_id AND ci.name = v.city_name
WHERE NOT EXISTS (
    SELECT 1 FROM attractions a
    WHERE a.name = v.name AND a.city_id = ci.city_id
);


-- Партия 09: 10 объектов в ранее не представленных странах.
INSERT INTO cities (country_id, name)
SELECT co.country_id, v.city_name
FROM (VALUES
('Центральноафриканская Республика','Национальный парк Маново-Гунда-Сен-Флорис'),
('Доминика','Национальный парк Морн-Труа-Питон'),
('Ямайка','Голубые и Джон-Кроу горы'),
('Парагвай','Тринидад'),
('Филиппины','Батад'),
('Катар','Эз-Зубара'),
('Саудовская Аравия','Хегра'),
('Словения','Шкоцян'),
('Таджикистан','Саразм'),
('Того','Кутаммаку')
) AS v(country_name, city_name)
JOIN countries co ON co.name = v.country_name
ON CONFLICT (country_id, name) DO NOTHING;

INSERT INTO attractions
 (name, description, history, latitude, longitude, category_id, city_id)
SELECT v.name, v.description, v.history, v.latitude, v.longitude, cat.category_id, ci.city_id
FROM (VALUES
('Национальный парк Маново-Гунда-Сен-Флорис','Обширная охраняемая природная территория саванн, пойменных лугов и лесных массивов на северо-востоке Центральноафриканской Республики. Парк известен крупными популяциями диких животных и разнообразием экосистем Судано-Сахельской зоны.','Парк включён в Список всемирного наследия ЮНЕСКО в 1988 году по природным критериям. С 1997 года он находится в Списке всемирного наследия под угрозой из-за браконьерства, отсутствия эффективного управления и других факторов, угрожающих сохранности природного комплекса.',9.000000::numeric,21.500000::numeric,'Природные объекты','Центральноафриканская Республика','Национальный парк Маново-Гунда-Сен-Флорис'),
('Национальный парк Морн-Труа-Питон','Природная территория вулканического происхождения с тропическими лесами, крутыми склонами, горячими источниками, фумаролами, пресноводными озёрами и знаменитым Кипящим озером.','Парк охраняет центральную горную часть острова Доминика и включает вулкан Морн-Труа-Питон высотой 1 342 метра. Он был включён в Список всемирного наследия ЮНЕСКО в 1997 году благодаря сочетанию геологических процессов и богатого биоразнообразия.',15.331113::numeric,-61.306610::numeric,'Природные объекты','Доминика','Национальный парк Морн-Труа-Питон'),
('Голубые и Джон-Кроу горы','Горный природно-культурный ландшафт на востоке Ямайки с влажными тропическими лесами, высокой долей эндемичных видов и историческими маршрутами марунов.','Горный регион служил убежищем для коренных жителей и позднее для марунов — потомков порабощённых африканцев, бежавших из колониального рабства. Ландшафт сочетает природное разнообразие и свидетельства сопротивления и сохранения культурных традиций; объект включён в Список всемирного наследия ЮНЕСКО в 2015 году.',18.077500::numeric,-76.571111::numeric,'Природные объекты','Ямайка','Голубые и Джон-Кроу горы'),
('Иезуитские миссии Ла-Сантисима-Тринидад-де-Парана и Хесус-де-Таваранге','Археологические остатки двух миссионерских поселений с храмами, площадями, жилыми и общественными постройками, отражающими взаимодействие европейской и гуаранийской культур.','Миссии были основаны иезуитами в XVII–XVIII веках в бассейне реки Ла-Плата. Комплексы демонстрируют особую градостроительную модель редукций и синтез местных художественных традиций с христианской символикой. Объект включён в Список всемирного наследия ЮНЕСКО в 1993 году.',-27.132306::numeric,-55.702028::numeric,'Археологические памятники','Парагвай','Тринидад'),
('Рисовые террасы Кордильер Филиппин','Живой культурный ландшафт Ифугао: амфитеатральные террасы Батад, традиционные деревни, каменные и земляные подпорные стены и сложные ирригационные системы в горной местности острова Лусон.','Террасы создавались и поддерживались общинами Ифугао на протяжении примерно двух тысячелетий. Они отражают устойчивую систему земледелия, коллективного труда и передачи традиционных знаний между поколениями; объект включён в Список всемирного наследия ЮНЕСКО в 1995 году.',16.924444::numeric,121.065556::numeric,'Исторические места','Филиппины','Батад'),
('Археологический объект Эз-Зубара','Остатки укреплённого прибрежного города XVIII–XIX веков с городской стеной, улицами, жилыми кварталами, мечетями, рынком и гаванью.','Эз-Зубара был важным центром торговли жемчугом и одним из наиболее значимых торговых поселений региона Персидского залива. Город был оставлен в начале XX века; сохранившиеся археологические структуры дают представление о торговле, городской жизни и экономике региона. Объект включён в Список всемирного наследия ЮНЕСКО в 2013 году.',25.978056::numeric,51.029722::numeric,'Археологические памятники','Катар','Эз-Зубара'),
('Археологический комплекс Хегра (аль-Хиджр / Мадаин-Салих)','Набатейский археологический комплекс с монументальными скальными гробницами, фасадами, надписями и остатками древнего поселения в пустынном ландшафте северо-западной Аравии.','Хегра была крупным южным центром Набатейского царства и важным пунктом торговых путей. Наиболее известны высеченные в скалах гробницы I века до н. э. — I века н. э.; объект стал первым объектом Саудовской Аравии в Списке всемирного наследия ЮНЕСКО в 2008 году.',26.783611::numeric,37.955000::numeric,'Археологические памятники','Саудовская Аравия','Хегра'),
('Пещеры Шкоцян','Система известняковых пещер с одним из крупнейших известных подземных каньонов Европы, карстовыми залами, провалами и подземным течением реки Река.','Пещерный комплекс сформировался в карстовом плато Крас и известен масштабными подземными формами рельефа и археологическими свидетельствами посещения человеком с доисторических времён. Пещеры включены в Список всемирного наследия ЮНЕСКО в 1986 году.',45.666670::numeric,14.000000::numeric,'Природные объекты','Словения','Шкоцян'),
('Прото-городище Саразм','Археологический комплекс древнего поселения в долине Зеравшана, свидетельствующий о раннем развитии земледелия, металлургии, ремёсел и дальних торговых связей в Центральной Азии.','Поселение существовало примерно с IV до конца III тысячелетия до н. э. и было одним из ранних центров оседлой культуры региона. Археологические находки указывают на связи с территориями от степей Центральной Азии до Иранского нагорья и Индийского субконтинента; объект включён в Список всемирного наследия ЮНЕСКО в 2010 году.',39.507889::numeric,67.458722::numeric,'Археологические памятники','Таджикистан','Саразм'),
('Кутаммаку — страна Батаммариба','Живой культурный ландшафт на северо-востоке Того, известный традиционными глинобитными башенными домами такьента, поселениями, сельскохозяйственными угодьями и священными природными местами народа батаммариба.','Архитектура такьента отражает социальную организацию и мировоззрение батаммариба, а культурный ландшафт сохраняет тесную связь между поселениями, природой и ритуальными практиками. Объект был включён в Список всемирного наследия ЮНЕСКО в 2004 году; в 2023 году объект расширили на соседнюю часть Бенина.',10.066667::numeric,1.133333::numeric,'Архитектура','Того','Кутаммаку')
) AS v(name, description, history, latitude, longitude, category_name, country_name, city_name)
JOIN categories cat ON cat.name = v.category_name
JOIN countries co ON co.name = v.country_name
JOIN cities ci ON ci.country_id = co.country_id AND ci.name = v.city_name
WHERE NOT EXISTS (
    SELECT 1 FROM attractions a
    WHERE a.name = v.name AND a.city_id = ci.city_id
);

-- Партия 10: 10 объектов всемирного наследия в ранее не представленных странах.
INSERT INTO cities (country_id, name)
SELECT co.country_id, v.city_name
FROM (VALUES
('Андорра','Долина Мадриу-Перафита-Кларор'),
('Венесуэла','Национальный парк Канайма'),
('Вьетнам','Бухта Халонг'),
('Замбия','Водопад Виктория'),
('Зимбабве','Большой Зимбабве'),
('Израиль','Масада'),
('Казахстан','Туркестан'),
('Кыргызстан','Ош'),
('Латвия','Рига'),
('Сингапур','Сингапур')
) AS v(country_name, city_name)
JOIN countries co ON co.name = v.country_name
ON CONFLICT (country_id, name) DO NOTHING;

INSERT INTO attractions
 (name, description, history, latitude, longitude, category_id, city_id)
SELECT v.name, v.description, v.history, v.latitude, v.longitude, cat.category_id, ci.city_id
FROM (VALUES
('Долина Мадриу-Перафита-Кларор','Высокогорный культурный ландшафт Андорры с ледниковыми долинами, пастбищами, каменными хижинами, тропами и традиционными сооружениями, связанными с сезонным скотоводством.','Долина отражает многовековое взаимодействие человека с горной средой Пиренеев. Сохранившиеся террасы, пастбища, тропы и постройки показывают развитие традиционного хозяйства и управления природными ресурсами; объект включён в Список всемирного наследия ЮНЕСКО в 2004 году.',42.494722::numeric,1.595556::numeric,'Природные объекты','Андорра','Долина Мадриу-Перафита-Кларор'),
('Национальный парк Канайма','Обширный природный комплекс на Гвианском плоскогорье с тепуи — столовыми горами с отвесными стенами, водопадами, саваннами и тропическими лесами.','Парк охватывает уникальные геологические образования и экосистемы, изолированные на древних песчаниковых плато. На его территории находится водопад Анхель; национальный парк включён в Список всемирного наследия ЮНЕСКО в 1994 году.',5.337994::numeric,-62.037883::numeric,'Природные объекты','Венесуэла','Национальный парк Канайма'),
('Бухта Халонг — архипелаг Катба','Морской карстовый ландшафт северного Вьетнама с тысячами известняковых островов и скал, бухтами, пещерами и прибрежными экосистемами.','Карстовый рельеф формировался в течение длительного геологического времени под воздействием тектонических процессов и эрозии. Бухта Халонг была включена в Список всемирного наследия ЮНЕСКО в 1994 году; в 2023 году объект расширили, включив архипелаг Катба.',20.832778::numeric,107.161111::numeric,'Природные объекты','Вьетнам','Бухта Халонг'),
('Водопад Виктория — Моси-оа-Тунья','Крупный водопад на реке Замбези, где вода падает в узкое базальтовое ущелье; окружающая территория включает речные острова, пороги и прибрежные экосистемы.','Местное название Моси-оа-Тунья переводится как «гремящий дым». Объект Всемирного наследия является трансграничным и расположен в Замбии и Зимбабве; он включён в список ЮНЕСКО в 1989 году. В этой записи использована географическая точка UNESCO для объекта со стороны Замбии.',-17.924530::numeric,25.855390::numeric,'Природные объекты','Замбия','Водопад Виктория'),
('Большой Зимбабве','Археологический комплекс каменных сооружений с массивными сухими кладками, включая Большую ограду, долинные руины и комплекс на холме.','Город был крупным политическим, экономическим и торговым центром юга Африки в период приблизительно с XI по XV век и связан с государством и культурой шона. Монументальные стены возводились без раствора; объект включён в Список всемирного наследия ЮНЕСКО в 1986 году.',-20.271170::numeric,30.933269::numeric,'Археологические памятники','Зимбабве','Большой Зимбабве'),
('Масада','Древняя крепость и дворцовый комплекс на изолированном скальном плато над Мёртвым морем, включающий дворцы, склады, казармы, цистерны и оборонительные сооружения.','Укрепления и дворцовые здания были значительно расширены Иродом Великим в I веке до н. э. Масада стала местом последнего сопротивления группы иудейских повстанцев римским войскам в 73/74 году н. э.; объект включён в Список всемирного наследия ЮНЕСКО в 2001 году.',31.315556::numeric,35.353611::numeric,'Исторические места','Израиль','Масада'),
('Мавзолей Ходжи Ахмеда Ясави','Монументальный мавзолей в Туркестане, выдающийся образец архитектуры эпохи Тимуридов с порталом, куполом, залами и богато декорированными интерьерами.','Строительство началось по приказу Тимура в 1389 году и продолжалось до его смерти в 1405 году, после чего здание осталось незавершённым. Комплекс связан с почитанием суфийского наставника Ходжи Ахмеда Ясави и включён в Список всемирного наследия ЮНЕСКО в 2003 году.',43.297694::numeric,68.271056::numeric,'Архитектура','Казахстан','Туркестан'),
('Священная гора Сулайман-Тоо','Известняковая гора в центре Оша с пещерами, культовыми местами, тропами и панорамными видами на Ферганскую долину.','Гора была местом почитания доисламских и исламских традиций и сохраняет свидетельства религиозных практик на протяжении многих столетий. На её склонах находятся места паломничества и петроглифы; объект включён в Список всемирного наследия ЮНЕСКО в 2009 году.',40.531111::numeric,72.782778::numeric,'Исторические места','Кыргызстан','Ош'),
('Исторический центр Риги','Историческое ядро столицы Латвии с плотной средневековой уличной сетью, зданиями ганзейского периода, архитектурой ар-нуво и деревянной застройкой XIX века.','Рига была основана в 1201 году и стала важным центром торговли и Ганзейского союза. Исторический центр сохраняет архитектурные слои разных эпох, особенно значительный ансамбль зданий модерна; объект включён в Список всемирного наследия ЮНЕСКО в 1997 году.',56.954170::numeric,24.116670::numeric,'Архитектура','Латвия','Рига'),
('Сингапурский ботанический сад','Исторический тропический ботанический сад и культурный ландшафт с озёрами, тематическими коллекциями растений, историческими зданиями и научно-образовательной инфраструктурой.','Сад был основан на нынешнем месте в 1859 году и сыграл важную роль в развитии тропической ботаники и распространении культуры выращивания каучука в Юго-Восточной Азии. Объект включён в Список всемирного наследия ЮНЕСКО в 2015 году.',1.315278::numeric,103.816111::numeric,'Природные объекты','Сингапур','Сингапур')
) AS v(name, description, history, latitude, longitude, category_name, country_name, city_name)
JOIN categories cat ON cat.name = v.category_name
JOIN countries co ON co.name = v.country_name
JOIN cities ci ON ci.country_id = co.country_id AND ci.name = v.city_name
WHERE NOT EXISTS (
    SELECT 1 FROM attractions a
    WHERE a.name = v.name AND a.city_id = ci.city_id
);

-- Партия 11: 10 объектов всемирного наследия в ранее не представленных странах.
INSERT INTO cities (country_id, name)
SELECT co.country_id, v.city_name
FROM (VALUES
('Малайзия','Мелака'),
('Объединённые Арабские Эмираты','Аль-Айн'),
('Панама','Остров Койба'),
('Северная Македония','Охрид'),
('Швейцария','Берн'),
('Украина','Львов'),
('Монголия','Хархорин'),
('Оман','Бахла'),
('Сан-Марино','Сан-Марино'),
('Южно-Африканская Республика','Роббен-Айленд')
) AS v(country_name, city_name)
JOIN countries co ON co.name = v.country_name
ON CONFLICT (country_id, name) DO NOTHING;

INSERT INTO attractions
 (name, description, history, latitude, longitude, category_id, city_id)
SELECT v.name, v.description, v.history, v.latitude, v.longitude, cat.category_id, ci.city_id
FROM (VALUES
('Исторический центр Мелаки','Исторический портовый город на Малаккском проливе с административными зданиями, церквями, площадями и укреплениями, отражающими малайское, португальское, нидерландское и британское наследие.','Мелака развивалась более пяти столетий как важный торговый порт на маршрутах между Востоком и Западом. Её архитектурный облик отражает эпоху Малаккского султаната XV века и последующие португальский, нидерландский и британский периоды. Вместе с Джорджтауном объект включён в Список всемирного наследия ЮНЕСКО в 2008 году.',2.191667::numeric,102.262500::numeric,'Исторические места','Малайзия','Мелака'),
('Археологический парк Хили','Археологическая зона в оазисе Аль-Айн с поселениями бронзового века, круглыми каменными гробницами, остатками построек и древней системой ирригации афладж.','Археологические памятники Хили свидетельствуют о развитии оседлых сообществ в пустынном регионе в бронзовом и железном веках. Комплекс входит в серийный объект «Культурные объекты Аль-Айна», включённый в Список всемирного наследия ЮНЕСКО в 2011 году.',24.292883::numeric,55.789914::numeric,'Археологические памятники','Объединённые Арабские Эмираты','Аль-Айн'),
('Национальный парк Койба','Островной и морской природный комплекс в заливе Чирики, включающий остров Койба, десятки малых островов, тропические леса и обширные морские охраняемые территории.','Остров Койба долгое время оставался изолированным, что способствовало сохранению эндемичных видов и природных сообществ. Национальный парк и специальная зона морской охраны включены в Список всемирного наследия ЮНЕСКО в 2005 году как важный природный коридор восточной части Тихого океана.',7.433000::numeric,-81.766000::numeric,'Природные объекты','Панама','Остров Койба'),
('Природное и культурное наследие Охридского региона','Трансграничный ландшафт вокруг древнего озера Охрид, сочетающий эндемичные пресноводные экосистемы, историческую городскую застройку, церкви, монастыри и археологические памятники.','Озеро Охрид существует около двух-трёх миллионов лет и служит убежищем для многочисленных эндемичных видов. Город Охрид сохраняет ансамбль архитектуры и религиозного искусства VII–XIX веков. Объект был включён в список ЮНЕСКО в 1979 году по природным критериям, в 1980 году расширен культурной составляющей и в 2019 году дополнен албанской частью.',41.028000::numeric,20.722000::numeric,'Исторические места','Северная Македония','Охрид'),
('Старый город Берна','Средневековый исторический центр столицы Швейцарии на холме, окружённом рекой Ааре, с аркадами, фонтанами, историческими улицами и зданиями из песчаника.','Берн был основан в XII веке по единому градостроительному замыслу. Средневековая планировка сохранилась несмотря на последующие этапы расширения и перестройки; аркады и фонтаны XVI века являются характерными элементами города. Старый город включён в Список всемирного наследия ЮНЕСКО в 1983 году.',46.948061::numeric,7.450281::numeric,'Архитектура','Швейцария','Берн'),
('Ансамбль исторического центра Львова','Исторический городской ансамбль с рыночной площадью, средневековой уличной сетью, храмами и архитектурой, отражающей взаимодействие восточноевропейских культурных традиций.','Львов развивался как важный торговый и культурный центр на пересечении путей между Востоком и Западом. Историческая застройка включает элементы разных архитектурных периодов и свидетельствует о многокультурной истории города. Ансамбль исторического центра включён в Список всемирного наследия ЮНЕСКО в 1998 году.',49.841667::numeric,24.031944::numeric,'Архитектура','Украина','Львов'),
('Культурный ландшафт долины Орхона','Обширный степной культурный ландшафт вдоль реки Орхон с археологическими памятниками кочевых государств, древними поселениями и руинами Каракорума.','Долина Орхона отражает многовековую историю кочевых обществ Центральной Азии и их взаимодействие с административными и религиозными центрами. В состав объекта входит Каракорум — столица Монгольской империи XIII–XIV веков. Культурный ландшафт включён в Список всемирного наследия ЮНЕСКО в 2004 году.',47.479214::numeric,102.678482::numeric,'Археологические памятники','Монголия','Хархорин'),
('Крепость Бахла','Крупная глинобитная крепость с башнями и стенами на каменном основании, расположенная рядом с историческим поселением и пальмовой рощей в оазисе Бахла.','Оазис Бахла процветал под властью племени Бану Набхан, доминировавшего в регионе с XII до конца XV века. Крепость свидетельствует о политическом и экономическом влиянии племени и традициях оборонительной архитектуры Омана. Объект включён в Список всемирного наследия ЮНЕСКО в 1987 году.',22.964169::numeric,57.301111::numeric,'Исторические места','Оман','Бахла'),
('Исторический центр Сан-Марино и гора Титано','Исторический центр города-государства на горе Титано с крепостными башнями, стенами, воротами, бастионами, монастырями и общественными зданиями.','Исторический центр отражает непрерывность существования свободной республики со времён Средневековья. Городская структура и оборонительные сооружения сохранили свидетельства развития итальянских городов-государств; объект включён в Список всемирного наследия ЮНЕСКО в 2008 году.',43.932778::numeric,12.451944::numeric,'Исторические места','Сан-Марино','Сан-Марино'),
('Остров Роббен','Остров у побережья Кейптауна с бывшей тюрьмой строгого режима, историческими административными зданиями, маяком и другими сооружениями разных эпох.','С XVII по XX век остров использовался как тюрьма, лечебное учреждение и военная база. Тюрьма периода апартеида стала символом политических репрессий и последующей победы демократии над угнетением. Остров Роббен включён в Список всемирного наследия ЮНЕСКО в 1999 году.',-33.800000::numeric,18.366667::numeric,'Исторические места','Южно-Африканская Республика','Роббен-Айленд')
) AS v(name, description, history, latitude, longitude, category_name, country_name, city_name)
JOIN categories cat ON cat.name = v.category_name
JOIN countries co ON co.name = v.country_name
JOIN cities ci ON ci.country_id = co.country_id AND ci.name = v.city_name
WHERE NOT EXISTS (
    SELECT 1 FROM attractions a
    WHERE a.name = v.name AND a.city_id = ci.city_id
);


-- Партия 12: 9 новых стран и дополнительный объект в уже представленной Румынии.
INSERT INTO cities (country_id, name)
SELECT co.country_id, v.city_name
FROM (VALUES
('Мьянма','Ньяунг-У'),
('Черногория','Котор'),
('Словакия','Банска-Штьявница'),
('Мальдивы','Мале'),
('Уругвай','Фрай-Бентос'),
('Пакистан','Лахор'),
('Судан','Карима'),
('Йемен','Сана'),
('Суринам','Сипаливини'),
('Руанда','Кигали')
) AS v(country_name, city_name)
JOIN countries co ON co.name = v.country_name
ON CONFLICT (country_id, name) DO NOTHING;

INSERT INTO attractions
 (name, description, history, latitude, longitude, category_id, city_id)
SELECT v.name, v.description, v.history, v.latitude, v.longitude, cat.category_id, ci.city_id
FROM (VALUES
('Баган','Обширный археологический ландшафт на равнине центральной Мьянмы, включающий тысячи буддийских храмов, пагод, монастырей и археологических остатков.','Баган был столицей Паганского царства в IX–XIII веках и одним из важнейших центров буддизма в регионе. Сохранившиеся религиозные сооружения отражают развитие архитектуры, искусства и политической истории Мьянмы. Объект включён в Список всемирного наследия ЮНЕСКО в 2019 году.',21.148889::numeric,94.884439::numeric,'Археологические памятники','Мьянма','Ньяунг-У'),
('Природный и культурно-исторический регион Котора','Прибрежный ландшафт Которского залива с историческим городом, средневековыми укреплениями, поселениями и памятниками в окружении гор.','Регион развивался как важный морской и торговый центр Адриатики. Архитектура Котора и прибрежных поселений отражает взаимодействие средиземноморских культур и многовековую историю мореплавания. Объект включён в Список всемирного наследия ЮНЕСКО в 1979 году.',42.483330::numeric,18.700000::numeric,'Исторические места','Черногория','Котор'),
('Исторический город Банска-Штьявница и технические памятники в окрестностях','Исторический горнодобывающий город в центральной Словакии с площадями, церквями, замковыми сооружениями и техническими памятниками горного дела.','Развитие города было связано с добычей серебра и золота, а также с внедрением передовых горных и гидротехнических технологий. В XVIII веке здесь действовала одна из первых горных академий Европы. Объект включён в Список всемирного наследия ЮНЕСКО в 1993 году.',48.461110::numeric,18.900000::numeric,'Исторические места','Словакия','Банска-Штьявница'),
('Пятничная мечеть Мале','Историческая мечеть из резного кораллового камня на острове Мале, входящая в ансамбль традиционных коралловых мечетей Мальдивских островов.','Нынешняя мечеть была построена в 1658 году при султане Ибрагиме Искандаре I на месте более ранней мечети, основанной после принятия ислама в 1153 году. Комплекс включает минарет, коралловые колодцы, солнечные часы и историческое кладбище. Объект включён в Предварительный список всемирного наследия ЮНЕСКО в составе Coral Stone Mosques of Maldives.',4.177997::numeric,73.512378::numeric,'Религиозные сооружения','Мальдивы','Мале'),
('Промышленный ландшафт Фрай-Бентоса','Исторический промышленный комплекс на берегу реки Уругвай с производственными зданиями, портовой инфраструктурой и жилыми объектами бывшего мясоперерабатывающего предприятия.','Комплекс возник вокруг предприятия Liebig’s Extract of Meat Company, основанного в XIX веке, и стал важным центром производства мясных экстрактов и консервированной продукции. Ландшафт отражает развитие глобальной пищевой промышленности и международной торговли. Объект включён в Список всемирного наследия ЮНЕСКО в 2015 году.',-33.117778::numeric,-58.331667::numeric,'Исторические места','Уругвай','Фрай-Бентос'),
('Форт Лахора и сады Шалимар','Серийный объект, объединяющий крепость Лахора с дворцовыми сооружениями и сады Шалимар — образец могольского садово-паркового искусства.','Крепость и сады отражают расцвет могольской архитектуры при императорах Акбаре, Джахангире и Шах-Джахане в XVI–XVII веках. Комплекс демонстрирует развитие оборонительного, дворцового и ландшафтного строительства. Объект включён в Список всемирного наследия ЮНЕСКО в 1981 году.',31.588383::numeric,74.315403::numeric,'Архитектура','Пакистан','Лахор'),
('Гебель-Баркал и памятники Напатского региона','Археологический комплекс в долине Нила, включающий священную гору Гебель-Баркал, храмы, пирамиды и связанные с древним царством Куш памятники.','Регион был важным религиозным и политическим центром царства Куш. Памятники отражают взаимодействие древнеегипетских и местных нубийских традиций, а также историю правителей Напаты и Мероэ. Объект включён в Список всемирного наследия ЮНЕСКО в 2003 году.',18.537000::numeric,31.828028::numeric,'Археологические памятники','Судан','Карима'),
('Старый город Саны','Исторический центр столицы Йемена с плотной застройкой многоэтажными домами из сырцового кирпича, мечетями, банями и традиционными садами.','Сана непрерывно заселялась более 2 500 лет и стала крупным центром распространения ислама в VII–VIII веках. Архитектурный облик старого города сформирован традиционными башенными домами с геометрическим декором из обожжённого кирпича и гипса. Объект включён в Список всемирного наследия ЮНЕСКО в 1986 году.',15.355556::numeric,44.208056::numeric,'Исторические места','Йемен','Сана'),
('Центральный природный резерват Суринама','Крупная охраняемая территория первичных тропических лесов центрально-западной части Суринама, включающая горные и равнинные экосистемы и верховья нескольких речных бассейнов.','Резерват был создан в 1998 году путём объединения нескольких ранее охраняемых территорий. Он сохраняет обширные массивы практически нетронутых лесов, высокое видовое разнообразие и местообитания редких животных. Объект включён в Список всемирного наследия ЮНЕСКО в 2000 году.',4.000000::numeric,-56.500000::numeric,'Природные объекты','Суринам','Сипаливини'),
('Мемориальные места геноцида: Ньямата, Мурамби, Гисози и Бисесеро','Серийный мемориальный объект из четырёх мест памяти, связанных с геноцидом против тутси в Руанде в 1994 году; включает мемориалы, места массовых убийств и захоронений.','Четыре компонента сохраняют свидетельства событий апреля—июля 1994 года и увековечивают память жертв. Мемориалы выполняют образовательную функцию и способствуют сохранению исторической памяти. Объект включён в Список всемирного наследия ЮНЕСКО в 2023 году.',-1.930944::numeric,30.060389::numeric,'Исторические места','Руанда','Кигали')
) AS v(name, description, history, latitude, longitude, category_name, country_name, city_name)
JOIN categories cat ON cat.name = v.category_name
JOIN countries co ON co.name = v.country_name
JOIN cities ci ON ci.country_id = co.country_id AND ci.name = v.city_name
WHERE NOT EXISTS (
    SELECT 1 FROM attractions a
    WHERE a.name = v.name AND a.city_id = ci.city_id
);

-- Партия 13: 10 объектов в 10 новых странах; координаты по географическим данным UNESCO World Heritage Centre.
INSERT INTO cities (country_id, name)
SELECT co.country_id, v.city_name
FROM (VALUES
    ('Ирак', 'Вавилон'),
    ('Иран', 'Персеполис'),
    ('Ливия', 'Хомс'),
    ('Сирия', 'Дамаск'),
    ('Нигер', 'Арлит'),
    ('Уганда', 'Кисоро'),
    ('Мавритания', 'Нуадибу'),
    ('Эритрея', 'Асмэра'),
    ('Соломоновы Острова', 'Реннелл'),
    ('Антигуа и Барбуда', 'Инглиш-Харбор')
) AS v(country_name, city_name)
JOIN countries co ON co.name = v.country_name
ON CONFLICT (country_id, name) DO NOTHING;

INSERT INTO attractions
 (name, description, history, latitude, longitude, category_id, city_id)
SELECT v.name, v.description, v.history, v.latitude, v.longitude, cat.category_id, ci.city_id
FROM (VALUES
    ('Вавилон', 'Археологический комплекс древнего Вавилона с остатками городских стен, ворот, дворцов и храмов.', 'Вавилон был одним из крупнейших центров Месопотамии и столицей Нововавилонского царства в 626–539 годах до н. э. При Навуходоносоре II город получил монументальные стены, дворцовые ансамбли и храмовые сооружения.', 32.541969::numeric, 44.420833::numeric, 'Археологические памятники', 'Ирак', 'Вавилон'),
    ('Персеполис', 'Руины парадной столицы державы Ахеменидов с монументальной террасой, дворцами, лестницами и рельефами.', 'Строительство Персеполиса началось по приказу Дария I около 518 года до н. э. Комплекс развивали его преемники; он служил местом проведения царских церемоний и приёмов.', 29.934440::numeric, 52.890280::numeric, 'Археологические памятники', 'Иран', 'Персеполис'),
    ('Археологический комплекс Лептис-Магна', 'Остатки крупного римского города с форумом, базиликой, театром, термами, рынком и древней гаванью.', 'Поселение возникло как финикийский торговый порт в VII веке до н. э. При Римской империи, особенно во времена императора Септимия Севера в III веке н. э., город был значительно расширен и украшен.', 32.638330::numeric, 14.293060::numeric, 'Археологические памятники', 'Ливия', 'Хомс'),
    ('Старый город Дамаска', 'Исторический центр одного из древнейших непрерывно населённых городов Ближнего Востока с мечетями, рынками, цитаделью и традиционной городской застройкой.', 'Дамаск сформировался как важный городской центр в III тысячелетии до н. э. В VIII веке город был столицей Омейядского халифата; среди важнейших памятников — мечеть Омейядов, построенная на месте более ранних культовых сооружений.', 33.510833::numeric, 36.309722::numeric, 'Исторические места', 'Сирия', 'Дамаск'),
    ('Природные резерваты Аир и Тенере', 'Обширная охраняемая территория Сахары, включающая горный массив Аир и пустынные ландшафты Тенере.', 'Резерваты были включены в Список всемирного наследия ЮНЕСКО в 1991 году. Территория площадью около 7,7 млн гектаров сохраняет редкие сахаро-сахельские экосистемы и местообитания пустынной фауны.', 19.076193::numeric, 9.662000::numeric, 'Природные объекты', 'Нигер', 'Арлит'),
    ('Национальный парк Бвинди', 'Горный лесной массив с исключительно высоким биоразнообразием, известный как место обитания значительной части мировой популяции горных горилл.', 'Бвинди расположен на стыке равнинных и горных лесов юго-западной Уганды. Национальный парк был включён в Список всемирного наследия ЮНЕСКО в 1994 году благодаря богатству видов и сохранности афромонтанных лесов.', -1.047000::numeric, 29.692000::numeric, 'Природные объекты', 'Уганда', 'Кисоро'),
    ('Национальный парк Бан-д’Арген', 'Прибрежная природная территория с песчаными дюнами, отмелями, островами, болотами и мелководными морскими экосистемами.', 'Парк расположен на атлантическом побережье Мавритании и имеет международное значение для гнездования птиц и зимовки мигрирующих куликов. Объект был включён в Список всемирного наследия ЮНЕСКО в 1989 году.', 20.234720::numeric, -16.108890::numeric, 'Природные объекты', 'Мавритания', 'Нуадибу'),
    ('Асмэра — модернистский город Африки', 'Исторический городской ансамбль с рационалистической и модернистской архитектурой, общественными зданиями, кинотеатрами, храмами и жилыми кварталами.', 'Асмэра развивалась с 1890-х годов как итальянский колониальный административный и военный центр. В 1930-х годах город пережил масштабное строительство; его планировочная структура и архитектура отражают модернистские градостроительные идеи первой половины XX века.', 15.335278::numeric, 38.935833::numeric, 'Архитектура', 'Эритрея', 'Асмэра'),
    ('Восточный Реннелл', 'Природный объект на юге острова Реннелл, включающий поднятый коралловый атолл, озеро Тегано, тропические леса и прибрежную морскую зону.', 'Восточная часть острова Реннелл была включена в Список всемирного наследия ЮНЕСКО в 1998 году. Территория известна высокой эндемичностью флоры и фауны; это первый природный объект Всемирного наследия с традиционным общинным владением и управлением.', -11.683330::numeric, 160.333330::numeric, 'Природные объекты', 'Соломоновы Острова', 'Реннелл'),
    ('Антигуа-Навал-Докъярд и связанные археологические объекты', 'Комплекс георгианских военно-морских сооружений и укреплений в естественной гавани Инглиш-Харбор на острове Антигуа.', 'Верфь создавалась британским Королевским флотом для обслуживания кораблей в Карибском регионе. Её строительство и работа опирались на принудительный труд поколений порабощённых африканцев; объект включён в Список всемирного наследия ЮНЕСКО в 2016 году.', 17.006944::numeric, -61.761667::numeric, 'Исторические места', 'Антигуа и Барбуда', 'Инглиш-Харбор')
) AS v(name, description, history, latitude, longitude, category_name, country_name, city_name)
JOIN categories cat ON cat.name = v.category_name
JOIN countries co ON co.name = v.country_name
JOIN cities ci ON ci.country_id = co.country_id AND ci.name = v.city_name
WHERE NOT EXISTS (
    SELECT 1 FROM attractions a
    WHERE a.name = v.name AND a.city_id = ci.city_id
);

-- Партия 14: 10 объектов в 10 новых странах; статусы UNESCO уточнены в документации.
INSERT INTO cities (country_id, name)
SELECT co.country_id, v.city_name
FROM (VALUES
    ('Лесото', 'Сехлабатебе'),
    ('Маврикий', 'Порт-Луи'),
    ('Сейшельские Острова', 'Праслин'),
    ('Малави', 'Манки-Бей'),
    ('Вануату', 'Эфате'),
    ('Микронезия', 'Понпеи'),
    ('Молдова', 'Руди'),
    ('Бутан', 'Паро'),
    ('Джибути', 'Таджура'),
    ('Кувейт', 'Файлака')
) AS v(country_name, city_name)
JOIN countries co ON co.name = v.country_name
ON CONFLICT (country_id, name) DO NOTHING;

INSERT INTO attractions
 (name, description, history, latitude, longitude, category_id, city_id)
SELECT v.name, v.description, v.history, v.latitude, v.longitude, cat.category_id, ci.city_id
FROM (VALUES
    ('Национальный парк Сехлабатебе', 'Высокогорная охраняемая территория на востоке Лесото, входящая в трансграничный природный объект Малоти-Дракенсберг; известна базальтовыми массивами, альпийскими лугами, водопадами и наскальными рисунками.', 'Национальный парк Сехлабатебе является лесотским компонентом объекта Всемирного наследия «Парк Малоти-Дракенсберг», который объединяет охраняемые территории Лесото и Южно-Африканской Республики. Его включение расширило охрану биоразнообразия и культурного наследия региона.', -29.915278::numeric, 29.123056::numeric, 'Природные объекты', 'Лесото', 'Сехлабатебе'),
    ('Ааправаси-Гхат', 'Исторический иммиграционный комплекс в портовом районе Порт-Луи, связанный с прибытием на Маврикий наёмных рабочих из Индии.', 'В 1834 году британская администрация выбрала Маврикий для эксперимента с системой контрактного труда после отмены рабства. В период с 1834 по 1920 год через Ааправаси-Гхат прошло около полумиллиона работников. Комплекс включён в Список всемирного наследия ЮНЕСКО в 2006 году.', -20.158639::numeric, 57.503167::numeric, 'Исторические места', 'Маврикий', 'Порт-Луи'),
    ('Природный заповедник Валле-де-Мэ', 'Охраняемый лесной массив на острове Праслин с сохранившимися природными сообществами пальмовых лесов и эндемичными видами Сейшельских островов.', 'Заповедник сохраняет уникальную пальмовую экосистему, в том числе сейшельскую пальму коко-де-мер. Объект включён в Список всемирного наследия ЮНЕСКО в 1983 году.', -4.330999::numeric, 55.738000::numeric, 'Природные объекты', 'Сейшельские Острова', 'Праслин'),
    ('Национальный парк озера Малави', 'Охраняемая территория на южной оконечности озера Малави, включающая прибрежные участки, острова и водные экосистемы с исключительно высоким разнообразием рыб.', 'Озеро Малави известно сотнями видов цихлид, большая часть которых является эндемичной. Национальный парк был включён в Список всемирного наследия ЮНЕСКО в 1984 году как территория исключительной ценности для сохранения биоразнообразия.', -14.033330::numeric, 34.883330::numeric, 'Природные объекты', 'Малави', 'Манки-Бей'),
    ('Владения вождя Рои Маты', 'Культурный ландшафт, объединяющий три археологических места на островах Эфате, Лелепа и Арток, связанные с жизнью, смертью и наследием верховного вождя Рои Маты.', 'Объект отражает традиционные системы власти и устные предания центрального Вануату. Археологические места связаны с резиденцией вождя, местом его смерти и коллективным захоронением. Объект включён в Список всемирного наследия ЮНЕСКО в 2008 году.', -17.628069::numeric, 168.177719::numeric, 'Исторические места', 'Вануату', 'Эфате'),
    ('Нан-Мадол: церемониальный центр Восточной Микронезии', 'Комплекс более чем ста искусственных островков у юго-восточного побережья острова Понпеи с каменными дворцами, храмами, гробницами и жилыми сооружениями.', 'Нан-Мадол был церемониальным центром династии Сауделер и формировался в период примерно с 1200 по 1500 год. Сооружения из базальтовых и коралловых блоков свидетельствуют о сложной политической и религиозной организации общества. Объект включён в Список всемирного наследия ЮНЕСКО в 2016 году и находится в Списке всемирного наследия под угрозой.', 6.839722::numeric, 158.330833::numeric, 'Археологические памятники', 'Микронезия', 'Понпеи'),
    ('Геодезическая дуга Струве — пункт Руди', 'Геодезический пункт Руди в составе международной цепи триангуляционных измерений, протянувшейся от Северной Норвегии до Чёрного моря.', 'Измерения дуги проводились в 1816–1855 годах под руководством астронома Фридриха Георга Вильгельма Струве и помогли определить размеры и форму Земли. Пункт Руди является единственным компонентом объекта на территории Молдовы; сама дуга проходит через десять стран. Объект включён в Список всемирного наследия ЮНЕСКО в 2005 году.', 48.318889::numeric, 27.876667::numeric, 'Памятники', 'Молдова', 'Руди'),
    ('Древняя крепость Друкгьял-дзонг', 'Руины крепости на горном хребте в верхней части долины Паро, построенной для защиты западных подступов к Бутану.', 'Крепость была возведена в 1649 году правителем Шабдрунгом Нгавангом Намгьялом и использовалась в оборонительных целях. В 1951 году комплекс пострадал от пожара. Объект включён в Предварительный список всемирного наследия ЮНЕСКО в 2012 году; это не означает включения в основной Список всемирного наследия.', 27.500000::numeric, 89.333333::numeric, 'Исторические места', 'Бутан', 'Паро'),
    ('Озеро Ассаль', 'Бессточное солёное озеро в пустынной впадине Афар, окружённое вулканическими ландшафтами и соляными отложениями.', 'Озеро расположено примерно на 153 метра ниже уровня моря и является самой низкой точкой Африки. Его природные особенности связаны с рифтовой тектоникой и интенсивным испарением. Объект представлен в Предварительном списке всемирного наследия ЮНЕСКО с 2015 года, но не включён в основной список.', 11.683333::numeric, 42.416667::numeric, 'Природные объекты', 'Джибути', 'Таджура'),
    ('Остров Файлака — палимпсест человеческих цивилизаций', 'Остров в северо-западной части Персидского залива с археологическими свидетельствами длительного заселения и культурных контактов Месопотамии и региона Залива.', 'Файлака находилась на важных морских торговых путях. Археологические слои свидетельствуют о поселениях от конца III тысячелетия до н. э. до XIX века. Объект внесён Кувейтом в Предварительный список всемирного наследия ЮНЕСКО в 2025 году; он не является объектом основного Списка всемирного наследия.', 29.433333::numeric, 48.333333::numeric, 'Археологические памятники', 'Кувейт', 'Файлака')
) AS v(name, description, history, latitude, longitude, category_name, country_name, city_name)
JOIN categories cat ON cat.name = v.category_name
JOIN countries co ON co.name = v.country_name
JOIN cities ci ON ci.country_id = co.country_id AND ci.name = v.city_name
WHERE NOT EXISTS (
    SELECT 1 FROM attractions a
    WHERE a.name = v.name AND a.city_id = ci.city_id
);

-- Партия 15: 10 объектов в 10 ранее не представленных странах.
INSERT INTO cities (country_id, name)
SELECT co.country_id, v.city_name
FROM (VALUES
    ('Багамские Острова', 'Мэтью-Таун'),
    ('Бурунди', 'Гишора'),
    ('Коморы', 'Фомбони'),
    ('Гвинея', 'Лабе'),
    ('Гайана', 'Джорджтаун'),
    ('Гренада', 'Карриаку'),
    ('Кирибати', 'Кантон'),
    ('Сент-Люсия', 'Суфриер'),
    ('Палау', 'Корор'),
    ('Гвинея-Бисау', 'Бубаке')
) AS v(country_name, city_name)
JOIN countries co ON co.name = v.country_name
ON CONFLICT (country_id, name) DO NOTHING;

INSERT INTO attractions
 (name, description, history, latitude, longitude, category_id, city_id)
SELECT v.name, v.description, v.history, v.latitude, v.longitude, cat.category_id, ci.city_id
FROM (VALUES
    ('Национальный парк Инагуа', 'Крупная охраняемая территория на острове Большой Инагуа, включающая озеро Роса, солёные лагуны, солончаки и мангровые заросли; важнейшее место обитания фламинго и других водоплавающих птиц.', 'Парк охраняет крупнейшую наземную природную территорию Багамских Островов. Он включён в Предварительный список всемирного наследия ЮНЕСКО в 2015 году; это не означает включения в основной Список всемирного наследия.', 21.083333::numeric, -73.333333::numeric, 'Природные объекты', 'Багамские Острова', 'Мэтью-Таун'),
    ('Королевская резиденция Гишора', 'Традиционный королевский комплекс на холме Гишора, включающий двор царской резиденции и святилище священных барабанов.', 'Резиденция была основана королём Нтаре Руганбугой в первой половине XIX века. Комплекс связан с традициями королевского двора и ритуальными барабанами Бурунди; в 2026 году объект включён в Предварительный список всемирного наследия ЮНЕСКО.', -3.363056::numeric, 29.921944::numeric, 'Исторические места', 'Бурунди', 'Гишора'),
    ('Морской парк Мохели', 'Морская и прибрежная охраняемая территория вокруг острова Мохели с коралловыми рифами, морскими черепахами, дельфинами и другими представителями морского биоразнообразия.', 'Морской парк был создан в 2001 году и стал первой морской охраняемой территорией Коморских Островов. В 2026 году он был представлен в Предварительном списке всемирного наследия ЮНЕСКО.', -12.416667::numeric, 43.695278::numeric, 'Природные объекты', 'Коморы', 'Фомбони'),
    ('Массив Фута-Джаллон', 'Горный массив и высокогорное плато в Средней Гвинее, важный водораздел Западной Африки и источник нескольких крупных рек региона.', 'Фута-Джаллон имеет большое значение для гидрологии и экосистем Западной Африки. В 2026 году природный массив был включён Гвинеей в Предварительный список всемирного наследия ЮНЕСКО.', 11.845232::numeric, -11.339320::numeric, 'Природные объекты', 'Гвинея', 'Лабе'),
    ('Ратуша Джорджтауна', 'Историческое общественное здание в центре Джорджтауна, один из наиболее выразительных образцов деревянной неоготической архитектуры Карибского региона.', 'Здание было построено в 1887–1889 годах с использованием дерева и чугунных колонн. Ратуша представлена в Предварительном списке всемирного наследия ЮНЕСКО с 1995 года.', 6.833333::numeric, -58.200000::numeric, 'Архитектура', 'Гайана', 'Джорджтаун'),
    ('Гренадинская группа островов', 'Архипелаг небольших островов и рифов к югу от основных островов Гренадин, включающий Карриаку и соседние острова с коралловыми экосистемами.', 'Острова имеют общую природную и историческую связь с другими частями Гренадинского архипелага. Группа островов Гренадины была внесена Гренадой в Предварительный список всемирного наследия ЮНЕСКО в 2013 году.', 12.477222::numeric, -61.447222::numeric, 'Природные объекты', 'Гренада', 'Карриаку'),
    ('Охраняемая территория островов Феникс', 'Обширная морская охраняемая территория в центральной части Тихого океана, включающая восемь коралловых островов, атоллы, рифы и глубоководные экосистемы.', 'Территория сохраняет крупные практически нетронутые морские экосистемы. Она была включена в Список всемирного наследия ЮНЕСКО в 2010 году и является одним из крупнейших объектов такого типа.', -3.864454::numeric, -172.650203::numeric, 'Природные объекты', 'Кирибати', 'Кантон'),
    ('Охраняемая территория Питон', 'Природный и морской ландшафт на юго-западе острова Сент-Люсия, включающий вулканические пики Грос-Питон и Пти-Питон, леса и прибрежные воды.', 'Питоны представляют собой вулканические купола, возвышающиеся над Карибским морем. Охраняемая территория была включена в Список всемирного наследия ЮНЕСКО в 2004 году.', 13.807083::numeric, -61.070361::numeric, 'Природные объекты', 'Сент-Люсия', 'Суфриер'),
    ('Южная лагуна Скалистых островов', 'Морской и островной ландшафт в штате Корор, включающий сотни покрытых лесом известняковых островов, лагуны, коралловые рифы и морские озёра.', 'Скалистые острова представляют собой поднятые известняковые образования, сформированные вулканическими и карстовыми процессами. Археологические остатки свидетельствуют о заселении и использовании островов на протяжении тысячелетий. Объект включён в Список всемирного наследия ЮНЕСКО в 2012 году.', 7.246925::numeric, 134.352500::numeric, 'Природные объекты', 'Палау', 'Корор'),
    ('Прибрежные и морские экосистемы архипелага Бижагош — Омати Миньо', 'Обширная прибрежная и морская природная территория архипелага Бижагош, включающая мангровые леса, приливные отмели, острова и места размножения морских видов.', 'Архипелаг Бижагош состоит из многочисленных островов и илистых отмелей у атлантического побережья Западной Африки. Объект включён в Список всемирного наследия ЮНЕСКО в 2025 году.', 11.120000::numeric, -15.948889::numeric, 'Природные объекты', 'Гвинея-Бисау', 'Бубаке')
) AS v(name, description, history, latitude, longitude, category_name, country_name, city_name)
JOIN categories cat ON cat.name = v.category_name
JOIN countries co ON co.name = v.country_name
JOIN cities ci ON ci.country_id = co.country_id AND ci.name = v.city_name
WHERE NOT EXISTS (
    SELECT 1 FROM attractions a
    WHERE a.name = v.name AND a.city_id = ci.city_id
);

-- Партия 16: 10 объектов в 10 новых странах.
INSERT INTO cities (country_id, name)
SELECT co.country_id, v.city_name
FROM (VALUES
    ('Никарагуа', 'Пуэрто-Момотомбо'),
    ('КНДР', 'Пхеньян'),
    ('Папуа — Новая Гвинея', 'Маунт-Хаген'),
    ('Туркменистан', 'Мары'),
    ('Государство Палестина', 'Баттир'),
    ('Либерия', 'Монровия'),
    ('Сьерра-Леоне', 'Фритаун'),
    ('Южный Судан', 'Бома'),
    ('Тонга', 'Ниутуа'),
    ('Самоа', 'Уафато')
) AS v(country_name, city_name)
JOIN countries co ON co.name = v.country_name
ON CONFLICT (country_id, name) DO NOTHING;

INSERT INTO attractions
 (name, description, history, latitude, longitude, category_id, city_id)
SELECT v.name, v.description, v.history, v.latitude, v.longitude, cat.category_id, ci.city_id
FROM (VALUES
    ('Руины Леон-Вьехо', 'Археологические остатки раннего испанского колониального города, расположенные у вулкана Момотомбо на берегу озера Манагуа.', 'Город был основан в 1524 году и оставался важным ранним испанским поселением в Центральной Америке, пока извержение вулкана и землетрясения не привели к его оставлению в XVII веке. Руины включены в Список всемирного наследия ЮНЕСКО в 2000 году.', 12.400470::numeric, -86.616336::numeric, 'Археологические памятники', 'Никарагуа', 'Пуэрто-Момотомбо'),
    ('Комплекс гробниц Когурё', 'Группа древних погребальных сооружений королевства Когурё, включающая курганы с настенными росписями и погребальные камеры.', 'Гробницы относятся к периоду существования Когурё — одного из древних корейских государств. Росписи изображают повседневную жизнь, обряды, охоту и представления о загробном мире. Комплекс включён в Список всемирного наследия ЮНЕСКО в 2004 году.', 38.889444::numeric, 125.929722::numeric, 'Археологические памятники', 'КНДР', 'Пхеньян'),
    ('Раннеземледельческий памятник Кук', 'Археологический ландшафт заболоченной долины в высокогорье Новой Гвинеи, где сохранились следы древних систем осушения и выращивания культурных растений.', 'Археологические исследования показывают, что освоение болот и развитие земледельческих практик здесь продолжалось на протяжении тысячелетий. Находки свидетельствуют о самостоятельном развитии сельского хозяйства в регионе около 7000 лет назад. Объект включён в Список всемирного наследия ЮНЕСКО в 2008 году.', -5.783711::numeric, 144.331722::numeric, 'Археологические памятники', 'Папуа — Новая Гвинея', 'Маунт-Хаген'),
    ('Государственный историко-культурный парк «Древний Мерв»', 'Обширный археологический комплекс в оазисе Мерв, объединяющий остатки древних городов, крепостей, мавзолеев и оборонительных сооружений.', 'Мерв был одним из крупнейших центров Центральной Азии и важным узлом торговых путей. История поселений в оазисе насчитывает несколько тысячелетий; в разные эпохи здесь существовали города разных планировок и культурных традиций. Объект включён в Список всемирного наследия ЮНЕСКО в 1999 году.', 37.664831::numeric, 62.174892::numeric, 'Исторические места', 'Туркменистан', 'Мары'),
    ('Культурный ландшафт Баттир — земля оливок и виноградников', 'Традиционный сельскохозяйственный ландшафт к юго-западу от Иерусалима с каменными террасами, виноградниками, оливковыми рощами и древней системой распределения родниковой воды.', 'Террасное земледелие и система ирригации формировались на протяжении многих столетий и продолжают использоваться местными семьями. Ландшафт демонстрирует устойчивую адаптацию сельского хозяйства к горному рельефу. Объект включён в Список всемирного наследия ЮНЕСКО в 2014 году.', 31.724722::numeric, 35.128056::numeric, 'Исторические места', 'Государство Палестина', 'Баттир'),
    ('Остров Провиденс', 'Небольшой остров в устье реки Месурадо в Монровии, связанный с историей основания Либерии и прибытием освобождённых афроамериканцев.', 'Остров, ранее известный как Дозоа, был местом высадки освобождённых переселенцев из США в 1822 году и важным пунктом формирования раннего поселения, из которого выросла Либерия. Объект включён в Предварительный список всемирного наследия ЮНЕСКО в 2017 году и не является объектом основного списка.', 6.319349::numeric, -10.800984::numeric, 'Исторические места', 'Либерия', 'Монровия'),
    ('Остров Банс', 'Остров-крепость на реке Сьерра-Леоне, где сохранились руины торгового форпоста и укреплений, связанных с трансатлантической работорговлей.', 'Форт был основан в 1670 году и служил одним из ключевых пунктов вывоза порабощённых африканцев на американские рынки. Торговля прекратилась после запрета работорговли, а крепость была оставлена в XIX веке. Остров внесён в Предварительный список всемирного наследия ЮНЕСКО в 2012 году.', 8.571861::numeric, -13.045333::numeric, 'Исторические места', 'Сьерра-Леоне', 'Фритаун'),
    ('Миграционный ландшафт Бома — Бадингило', 'Обширная природная территория, объединяющая национальные парки Бома и Бадингило, пойменные луга, водно-болотные угодья и саванны Южного Судана.', 'Ландшафт поддерживает одну из крупнейших миграций наземных млекопитающих в мире: сезонные перемещения миллионов белоухих кобов, тиангов и газелей Монгалла. Объект был включён в Список всемирного наследия ЮНЕСКО по экстренной процедуре в 2026 году.', 6.941667::numeric, 33.277500::numeric, 'Природные объекты', 'Южный Судан', 'Бома'),
    ('Хаамонга-а-Мауи', 'Монументальный трилит из трёх массивных коралловых известняковых блоков в историческом комплексе Хекета на острове Тонгатапу.', 'Памятник традиционно связывают с правлением одиннадцатого туи-тонга Туʻитатуи и датируют XIII веком. Он рассматривается как часть древней столицы Хекета и свидетельствует о политической организации и монументальном строительстве раннего Тонганского государства. Комплекс включён в Предварительный список всемирного наследия ЮНЕСКО в 2007 году.', -21.136667::numeric, -175.048056::numeric, 'Памятники', 'Тонга', 'Ниутуа'),
    ('Природоохранная зона залива Фагалоа — Уафато — Тиавеа', 'Смешанный природно-культурный ландшафт на северо-востоке острова Уполу, включающий прибрежные тропические леса, горные склоны, водопады, коралловые рифы и традиционные деревни.', 'Территория сохраняет редкие лесные местообитания и отражает традиционный самоанский уклад faa-Samoa, включая управление природными ресурсами через местные общины и систему matai. Объект включён в Предварительный список всемирного наследия ЮНЕСКО в 2006 году.', -13.958333::numeric, -171.500000::numeric, 'Природные объекты', 'Самоа', 'Уафато')
) AS v(name, description, history, latitude, longitude, category_name, country_name, city_name)
JOIN categories cat ON cat.name = v.category_name
JOIN countries co ON co.name = v.country_name
JOIN cities ci ON ci.country_id = co.country_id AND ci.name = v.city_name
WHERE NOT EXISTS (
    SELECT 1 FROM attractions a
    WHERE a.name = v.name AND a.city_id = ci.city_id
);

-- Партия 17: 10 объектов в 10 новых странах.
INSERT INTO cities (country_id, name)
SELECT co.country_id, v.city_name
FROM (VALUES
    ('Конго', 'Одзала-Кокуа'),
    ('Маршалловы Острова', 'Бикини'),
    ('Святой Престол', 'Ватикан'),
    ('Сент-Винсент и Гренадины', 'Кингстаун'),
    ('Сент-Китс и Невис', 'Бастер'),
    ('Тринидад и Тобаго', 'Тобаго'),
    ('Тувалу', 'Нанумеа'),
    ('Экваториальная Гвинея', 'Монте-Ален'),
    ('Эсватини', 'Нгвеня'),
    ('Сан-Томе и Принсипи', 'Монте-Кафе')
) AS v(country_name, city_name)
JOIN countries co ON co.name = v.country_name
ON CONFLICT (country_id, name) DO NOTHING;

INSERT INTO attractions
 (name, description, history, latitude, longitude, category_id, city_id)
SELECT v.name, v.description, v.history, v.latitude, v.longitude, cat.category_id, ci.city_id
FROM (VALUES
    ('Лесной массив Одзала-Кокуа', 'Крупная охраняемая лесная территория на севере Республики Конго, включающая экосистемы тропических лесов и саванн и являющаяся важным убежищем для лесных слонов и приматов.', 'Территория национального парка Одзала-Кокуа имеет долгую историю природоохранной охраны; в 2023 году объект «Лесной массив Одзала-Кокуа» был включён в Список всемирного наследия ЮНЕСКО.', 1.335556::numeric, 14.860278::numeric, 'Природные объекты', 'Конго', 'Одзала-Кокуа'),
    ('Атолл Бикини — место ядерных испытаний', 'Атолл в составе Маршалловых Островов, где сохранились материальные свидетельства ядерных испытаний США, проводившихся в середине XX века.', 'На атолле в 1946–1958 годах проводились ядерные испытания, в ходе которых были переселены местные жители. Объект включён в Список всемирного наследия ЮНЕСКО в 2010 году как свидетельство эпохи ядерных испытаний.', 11.600000::numeric, 165.380556::numeric, 'Исторические места', 'Маршалловы Острова', 'Бикини'),
    ('Город-государство Ватикан', 'Историко-архитектурный ансамбль независимого города-государства, включающий собор Святого Петра, площадь, дворцы и сады.', 'Территория Ватикана связана с историей христианства и папства на протяжении почти двух тысячелетий. Ватикан включён в Список всемирного наследия ЮНЕСКО в 1984 году.', 41.902160::numeric, 12.457360::numeric, 'Религиозные сооружения', 'Святой Престол', 'Ватикан'),
    ('Петроглифы «Тринадцать камней»', 'Группа наскальных изображений на острове Сент-Винсент, выполненных на отдельных валунах и открытых скальных поверхностях.', 'Петроглифы входят в комплекс Rock Art of St. Vincent and the Grenadines, внесённый государством в Предварительный список всемирного наследия ЮНЕСКО в 2012 году. Предварительный статус не означает включения в основной Список.', 13.291389::numeric, -61.247778::numeric, 'Археологические памятники', 'Сент-Винсент и Гренадины', 'Кингстаун'),
    ('Историческая зона Бастера', 'Старейшая историческая часть Бастера — столицы острова Сент-Китс, с колониальной городской планировкой и архитектурой французского и британского периодов.', 'Бастер был основан французами около 1625 года, а в 1727 году стал британской столицей. Историческая зона включена в Предварительный список всемирного наследия ЮНЕСКО в 1998 году; это не основной Список.', 17.295500::numeric, -62.724600::numeric, 'Исторические места', 'Сент-Китс и Невис', 'Бастер'),
    ('Лесной заповедник Мейн-Ридж', 'Тропический лесной массив на острове Тобаго, сохраняющий значимые природные местообитания и водосборные территории.', 'Заповедник Мейн-Ридж считается одним из старейших охраняемых лесных резерватов региона. Объект внесён в Предварительный список всемирного наследия ЮНЕСКО в 2011 году; это не означает включения в основной Список.', 11.500000::numeric, -60.666667::numeric, 'Природные объекты', 'Тринидад и Тобаго', 'Тобаго'),
    ('Культурный ландшафт тихоокеанских атоллов Тувалу', 'Серийный культурный ландшафт, объединяющий атоллы и рифовые острова Тувалу, традиционные поселения, системы землепользования и морские пространства.', 'Ландшафт отражает традиционные способы жизни на низменных атоллах, коллективное управление ресурсами и адаптацию общин к ограниченным природным условиям. Объект внесён в Предварительный список всемирного наследия ЮНЕСКО в 2024 году; в нём представлены девять островов, включая Нанумеа.', -5.675000::numeric, 176.115556::numeric, 'Исторические места', 'Тувалу', 'Нанумеа'),
    ('Национальный парк Монте-Ален', 'Охраняемая природная территория континентальной части Экваториальной Гвинеи с влажными тропическими лесами и высокой биологической разнообразностью.', 'Национальный парк Монте-Ален расположен в центральной части материковой территории страны. Его природная ценность и биоразнообразие стали основанием для включения объекта в Предварительный список всемирного наследия ЮНЕСКО в 2026 году.', 1.816667::numeric, 10.250000::numeric, 'Природные объекты', 'Экваториальная Гвинея', 'Монте-Ален'),
    ('Древние рудники Нгвеня', 'Археологический горнодобывающий комплекс на северо-западе Эсватини, связанный с древней добычей гематита и использованием красного охристого пигмента.', 'Месторождения Нгвеня разрабатывались десятки тысяч лет назад; UNESCO описывает их как одно из древнейших свидетельств горнодобывающей деятельности. Объект включён в Предварительный список всемирного наследия ЮНЕСКО в 2008 году, но не в основной Список.', -26.197914::numeric, 31.082239::numeric, 'Археологические памятники', 'Эсватини', 'Нгвеня'),
    ('Рока Монте-Кафе', 'Историческая плантационная усадьба на острове Сан-Томе, входящая в серийный объект колониальных сельскохозяйственных комплексов архипелага.', 'Монте-Кафе — одна из шести рока, представляющих колониальную плантационную систему производства кофе и какао, основанную на принудительном труде и миграции. Серийный объект «Роки Сан-Томе и Принсипи: колониальная аграрная система и принудительная миграция» включён в Список всемирного наследия ЮНЕСКО в 2026 году.', 0.300611::numeric, 6.639722::numeric, 'Исторические места', 'Сан-Томе и Принсипи', 'Монте-Кафе')
) AS v(name, description, history, latitude, longitude, category_name, country_name, city_name)
JOIN categories cat ON cat.name = v.category_name
JOIN countries co ON co.name = v.country_name
JOIN cities ci ON ci.country_id = co.country_id AND ci.name = v.city_name
WHERE NOT EXISTS (
    SELECT 1 FROM attractions a
    WHERE a.name = v.name AND a.city_id = ci.city_id
);

-- Партия 18: завершающие 6 объектов для полного покрытия 195 стран.
INSERT INTO cities (country_id, name)
SELECT co.country_id, v.city_name
FROM (VALUES
    ('Бруней-Даруссалам', 'Бандар-Сери-Бегаван'),
    ('Лихтенштейн', 'Вадуц'),
    ('Монако', 'Монако'),
    ('Науру', 'Ярен'),
    ('Сомали', 'Могадишо'),
    ('Тимор-Лесте', 'Тутуала')
) AS v(country_name, city_name)
JOIN countries co ON co.name = v.country_name
ON CONFLICT (country_id, name) DO NOTHING;

INSERT INTO attractions
 (name, description, history, latitude, longitude, category_id, city_id)
SELECT v.name, v.description, v.history, v.latitude, v.longitude, cat.category_id, ci.city_id
FROM (VALUES
    ('Кампонг-Айер', 'Историческое водное поселение на реке Бруней в Бандар-Сери-Бегаване, состоящее из кварталов домов на сваях, деревянных настилов и мостов. Официальный туристический портал Брунея описывает его как одно из крупнейших водных поселений Юго-Восточной Азии.', 'Поселение имеет более чем тысячелетнюю историю и было историческим центром жизни на реке Бруней. Сегодня здесь действует культурно-туристическая галерея, посвящённая традициям водной деревни. Объект не числится в Предварительном списке UNESCO Брунея.', 4.882500::numeric, 114.942500::numeric, 'Исторические места', 'Бруней-Даруссалам', 'Бандар-Сери-Бегаван'),
    ('Замок Вадуц', 'Средневековый замок на холме над столицей Лихтенштейна, символ княжества и резиденция княжеской семьи. Замок закрыт для обычного посещения, но его внешний облик и панорама доступны с городских маршрутов.', 'Истоки замка относятся, вероятно, к XII веку; первое письменное упоминание датируется 1322 годом. В 1712 году замок перешёл во владение княжеского дома Лихтенштейнов, а с 1939 года служит постоянной резиденцией княжеской семьи. Лихтенштейн не является государством-участником Конвенции всемирного наследия UNESCO, поэтому объект не имеет статуса World Heritage или Tentative List.', 47.139440::numeric, 9.524440::numeric, 'Исторические места', 'Лихтенштейн', 'Вадуц'),
    ('Альпы Средиземноморья', 'Трансграничный геологический объект, объединяющий природные территории Франции, Италии и морскую акваторию, относящуюся в том числе к Монако. Вклад Монако в объект связан с морской частью; координата отражает точку, указанную в карточке страны в UNESCO.', 'Объект внесён Монако в Предварительный список всемирного наследия UNESCO 26 января 2017 года по природному критерию viii. Это трансграничная серия, а не объект, целиком расположенный в Монако; в ней участвуют Франция и Италия.', 43.347401::numeric, 7.587207::numeric, 'Природные объекты', 'Монако', 'Монако'),
    ('Командный хребет (Command Ridge)', 'Наивысшая точка острова Науру, где сохранились японские артиллерийские установки, бункер связи и другие следы военного присутствия периода Второй мировой войны.', 'Во время японской оккупации Науру в 1942–1945 годах на Командном хребте размещались зенитные орудия и наблюдательные позиции. Сохранившиеся реликты напоминают о военной истории острова. На момент подготовки партии объект не включён в Предварительный список UNESCO; страна в 2026 году уведомила ООН о смене официального названия на Республика Наоэро, однако справочник проекта сохраняет существующее наименование страны «Науру».', -0.533800::numeric, 166.916500::numeric, 'Исторические места', 'Науру', 'Ярен'),
    ('Маяк Могадишо Второй Лидо (Secondo-Lido)', 'Исторический маяк на набережной Могадишо, связанный с морской торговлей и портовой инфраструктурой побережья Индийского океана.', 'Маяк был построен в начале XX века в период итальянского колониального управления. Он включён в Предварительный список всемирного наследия UNESCO 22 января 2025 года как объект культурного наследия. В 2025 году UNESCO и специалисты по охране наследия провели техническую оценку частично обрушившегося сооружения и исторического окружения.', 2.034333::numeric, 45.344111::numeric, 'Исторические места', 'Сомали', 'Могадишо'),
    ('Национальный парк Нино-Конис-Сантана', 'Первая и крупнейшая охраняемая природная территория Тимор-Лесте, охватывающая восточную оконечность острова, прибрежные леса, водно-болотные угодья, коралловые рифы и морские экосистемы. Включает остров Жаку и озеро Ира-Лаларо.', 'Национальный парк был учреждён в 2007 году. 5 июня 2026 года UNESCO включила его в Мировую сеть биосферных резерватов как первый биосферный резерват Тимор-Лесте. Биосферный резерват UNESCO — отдельная программа и статус; он не означает включения в Список всемирного наследия или Предварительный список.', -8.445775::numeric, 127.159624::numeric, 'Природные объекты', 'Тимор-Лесте', 'Тутуала')
) AS v(name, description, history, latitude, longitude, category_name, country_name, city_name)
JOIN categories cat ON cat.name = v.category_name
JOIN countries co ON co.name = v.country_name
JOIN cities ci ON ci.country_id = co.country_id AND ci.name = v.city_name
WHERE NOT EXISTS (
    SELECT 1 FROM attractions a
    WHERE a.name = v.name AND a.city_id = ci.city_id
);
